/* ==========================================================================
   fiches.js — fiches explicatives (§7 du cahier des charges), chargé au premier
   clic sur ⓘ. Contenu statique ; structure de chaque fiche :
   { titre, phrase, mesure, calcul, interpreter, bouger, liens: [ids], piege }
   Les fiches des indicateurs sont rédigées à l'étape 4.
   ========================================================================== */
window.FICHES = {
"A1": {"titre": "Taux de la Fed — le taux effectif des fonds fédéraux", "phrase": "C'est le taux auquel les banques américaines se prêtent de l'argent d'un jour à l'autre, taux que la Fed (Réserve fédérale, la banque centrale des États-Unis) pilote par ses décisions.", "mesure": "Le prix de l'argent à très court terme aux États-Unis. La Fed n'impose pas ce taux : elle annonce une fourchette cible (un minimum et un maximum), et le taux observé sur le marché s'y place.", "calcul": "Chaque jour, on relève les taux réellement payés pour ces prêts entre banques et on en tire une valeur centrale, en tenant compte des montants échangés.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois depuis 1990, il a culminé à 9,52 % fin octobre 1990 (pic de fin de mois : les mois voisins étaient entre 7,6 et 8,1 %). Il est resté sous 0,5 % presque sans interruption de fin 2008 à fin 2016, puis de mars 2020 à avril 2022, avant de remonter à 5,33 % en janvier 2024.", "bouger": "La Fed le relève quand l'inflation (la hausse générale des prix) est trop forte, et le baisse quand l'économie faiblit. Il influence les crédits, l'épargne, la bourse et le dollar.", "liens": ["B2", "B3", "BC_10A3M", "A2", "t:points"], "piege": "Ce n'est pas la cible officielle, mais le taux effectif : il peut s'en écarter légèrement. La série s'affiche tous les jours, week-ends compris : la valeur est simplement reportée. Ses variations se mesurent en points de %."},
"A2": {"titre": "Taux de dépôt de la BCE — le taux directeur de la zone euro", "phrase": "C'est l'intérêt que la BCE (Banque centrale européenne) verse aux banques qui lui confient leur argent pour une nuit.", "mesure": "Le prix de l'argent à très court terme dans la zone euro. Plus ce taux est élevé, plus les banques préfèrent placer leurs fonds à la BCE plutôt que de les prêter à bas prix, ce qui tire les autres taux vers le haut.", "calcul": "Il n'est pas calculé : le Conseil des gouverneurs de la BCE le fixe lors de ses réunions. La courbe forme donc un escalier : une valeur identique jusqu'à la décision suivante.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois, il est resté négatif de juin 2014 à juin 2022, avec un minimum de −0,5 % : les banques payaient pour déposer leur argent. Son maximum est de 4,0 % en septembre 2023.", "bouger": "La BCE le fixe en fonction de l'inflation et de la croissance de la zone euro. Il guide l'Euribor (le taux auquel les banques européennes se prêtent entre elles, A3), les crédits à taux variable, l'épargne et le taux des emprunts d'État.", "liens": ["A3", "B5_10A", "C5", "B4", "A1"], "piege": "L'historique commence en 1999, avec la création de l'euro : il n'existe pas de taux de dépôt avant. Ce n'est pas le seul taux de la BCE. Un taux négatif n'est pas une erreur de la série : c'est réellement arrivé."},
"A3": {"titre": "Euribor 3 mois — le taux entre banques de la zone euro", "phrase": "L'Euribor 3 mois est le taux auquel des banques européennes se prêtent de l'argent pour trois mois.", "mesure": "Le coût de l'argent à trois mois entre banques. Il reflète ce que le marché attend des décisions de la BCE (Banque centrale européenne) dans les mois à venir, plus une petite marge de prudence. De nombreux crédits à taux variable y sont adossés.", "calcul": "L'EMMI (European Money Markets Institute), l'organisme qui gère cet indice, le calcule chaque jour à partir de données de banques. Notre série reprend la moyenne de chaque mois, publiée par la BCE.", "interpreter": "Il colle au taux de dépôt de la BCE, avec un peu d'avance. Dans nos données depuis 1994, son maximum est de 7,58 % en mars 1995. Il est resté négatif de mai 2015 à juin 2022, avec un minimum de −0,582 % en décembre 2021.", "bouger": "Les anticipations sur la BCE, et la confiance entre banques : en période de tension, il s'écarte du taux de dépôt. Il influence les crédits à taux variable et certains placements.", "liens": ["A2", "B5_10A", "C5", "B4"], "piege": "C'est une moyenne mensuelle, pas le taux du jour. L'historique commence en janvier 1994 : l'Euribor n'existe que depuis 1999, la série reconstitue donc un taux comparable avant cette date. Il existe aussi des Euribor à d'autres durées, que ce tableau ne suit pas."},
"A4": {"titre": "Bank Rate — le taux directeur de la Banque d'Angleterre", "phrase": "Le Bank Rate est le taux de référence fixé par la Banque d'Angleterre, la banque centrale du Royaume-Uni.", "mesure": "Le coût de base de l'argent au Royaume-Uni. C'est le taux que la banque centrale verse aux banques sur l'argent déposé chez elle : il se répercute sur les crédits et l'épargne britanniques.", "calcul": "Il n'est pas calculé : le comité de politique monétaire de la Banque d'Angleterre le fixe lors de ses réunions. La série est quotidienne, mais seulement les jours ouvrés, et sa courbe forme un escalier.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles, il valait 14,875 % en janvier 1990, début de la série. Il est tombé à 0,1 % en mars 2020. Il est resté à 0,5 % ou moins de mars 2009 à juillet 2018, puis de mars 2020 à février 2022.", "bouger": "La banque centrale le modifie selon l'inflation britannique et l'activité. Il influence la livre sterling, les crédits immobiliers, l'épargne et le taux des emprunts d'État britanniques.", "liens": ["B9", "C11", "A1", "A2"], "piege": "Ne le confondez pas avec le taux de votre crédit ou de votre épargne : ceux-ci se calculent à partir de lui, avec une marge propre à chaque banque. Ses variations se lisent en points de %. La dernière valeur date en général de la veille ouvrée."},
"A5": {"titre": "Taux au jour le jour du Japon — le taux de marché proche de la cible de la Banque du Japon", "phrase": "C'est le taux auquel les banques japonaises se prêtent de l'argent d'un jour à l'autre, sans garantie, taux que la Banque du Japon guide vers sa cible.", "mesure": "Le prix de l'argent à très court terme au Japon. La banque centrale vise un niveau, mais on observe un taux de marché : proche de la cible, jamais exactement égal.", "calcul": "La série vient de l'OCDE (Organisation de coopération et de développement économiques), via FRED (la base de données de la banque fédérale de réserve de Saint-Louis) : c'est la moyenne mensuelle des taux constatés sur le marché.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données depuis 1990, son maximum est de 8,2781 % en mars 1991. Il est resté sous 0,5 % pendant presque toute la période depuis 1995, et légèrement négatif de mars 2016 à février 2024 (minimum de −0,071 % en juin 2018).", "bouger": "Les décisions de la Banque du Japon, qui réagit à l'inflation japonaise et à la croissance. Il influence le yen, les crédits et le taux des emprunts d'État japonais.", "liens": ["B10", "C12", "A1", "A2"], "piege": "Ce n'est pas la cible, et la série est mensuelle. Si la série de l'OCDE prend du retard, le tableau la prolonge avec le taux quotidien publié par la Banque du Japon."},
"A6": {"titre": "Taux de référence chinois — le LPR à 1 an et son prédécesseur", "phrase": "C'est le taux de référence des crédits aux entreprises en Chine, orienté par la banque centrale chinoise.", "mesure": "Le coût de base du crédit à un an en Chine. La Chine n'a pas de taux directeur unique comme la Fed (Réserve fédérale, la banque centrale américaine) ou la BCE (Banque centrale européenne) : ce taux en tient lieu.", "calcul": "La série est composée par la BRI (Banque des règlements internationaux). Jusqu'en août 2019, c'est le taux de prêt de référence à un an ; ensuite, c'est le LPR (Loan Prime Rate, « taux préférentiel de prêt »), établi à partir des taux proposés par de grandes banques. Valeur de fin de mois.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Il est passé de 12,06 % en janvier 1996, premier point de la série, à 3,0 % en mai 2025, son minimum, avec des remontées temporaires, notamment jusqu'à 7,47 % en janvier 2008.", "bouger": "Les décisions de la banque centrale, qui cherche à soutenir la croissance sans emballer l'inflation ou l'immobilier. Il influence le crédit, la demande de matières premières et, indirectement, le yuan.", "liens": ["C13", "A1", "A2", "B11"], "piege": "Deux taux de nature différente sont enchaînés : le passage de 4,35 % à 4,25 % en août 2019 vient en partie du changement de définition. Taux très stable, qui ne bouge que de loin en loin. Historique depuis 1996 seulement, rien avant."},
"A7": {"titre": "Taux de la BNS — le taux directeur de la Suisse", "phrase": "C'est le taux de référence de la BNS (Banque nationale suisse), qui guide le prix de l'argent en Suisse.", "mesure": "Le coût de l'argent à très court terme en Suisse, pays à la monnaie très recherchée en temps de crise. La BNS s'en sert aussi pour limiter la hausse du franc suisse.", "calcul": "La série est composée par la BRI (Banque des règlements internationaux). De 1990 à 1999, c'est le taux d'escompte ; de 2000 à juin 2019, le milieu de la fourchette cible du Libor 3 mois (un taux interbancaire de Londres) ; depuis le 13 juin 2019, le taux directeur proprement dit.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles, son maximum est de 7,0 % en août 1991. Il est resté négatif de décembre 2014 à août 2022, avec un minimum de −0,75 % : parmi les sept taux directeurs suivis ici, c'est le seul à avoir été aussi bas.", "bouger": "Les décisions de la BNS, selon l'inflation suisse et la force du franc. Il influence le franc, les crédits et les taux suisses.", "liens": ["B12", "A2", "A1", "B4"], "piege": "Trois définitions successives sont mises bout à bout : les sauts d'un régime à l'autre ne sont pas tous des décisions de politique monétaire. La série est mensuelle et vient de la BRI, pas directement de la BNS."},
"B1": {"titre": "Taux à 10 ans des États-Unis — le grand taux de référence mondial", "phrase": "C'est le rendement annuel que demandent les investisseurs pour prêter à l'État américain pendant dix ans.", "mesure": "Le coût d'emprunt à long terme de la première économie mondiale. Il sert de repère à presque tous les taux longs : crédits immobiliers américains, obligations d'entreprises, valorisation des actions.", "calcul": "Chaque jour, le Trésor américain déduit des prix de marché de ses obligations le rendement d'un emprunt « à échéance constante » de dix ans. Quand le prix d'une obligation baisse, son rendement monte : les deux vont en sens inverse.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois depuis 1990, il a atteint 9,04 % en avril 1990 et 0,55 % en juillet 2020. Comparé au taux à 2 ans ou à 3 mois, il dit si la courbe des taux est pentue ou inversée.", "bouger": "Les attentes d'inflation, la croissance, la politique de la Fed (la banque centrale américaine), l'ampleur de la dette publique, et la ruée vers les placements sûrs en cas de crise (qui le fait baisser). Il influence la bourse, le dollar et l'immobilier.", "liens": ["B2", "B3", "A1", "BC_10A2A", "B4"], "piege": "Quand le taux monte, le prix des obligations déjà émises baisse. Un rendement n'est pas l'inflation. Les jours fériés américains, il n'y a pas de valeur : le trou reste un trou. Ses variations se lisent en points de %."},
"B10": {"titre": "Taux à 10 ans du Japon — le JGB", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à l'État japonais, via les JGB (Japanese Government Bonds, ses emprunts d'État).", "mesure": "Le coût d'emprunt à long terme du Japon, pays le plus endetté des grandes économies, avec une inflation longtemps absente. Il sert de repère aux placements en yens.", "calcul": "Le ministère des Finances japonais publie chaque jour ouvré le rendement à 10 ans, déduit des prix de marché de ses obligations.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois depuis 1990, il a atteint 8,105 % en septembre 1990 et −0,275 % en août 2019. Il est resté sous 0,5 % de façon quasi continue d'octobre 2014 à fin 2022.", "bouger": "Les décisions de la Banque du Japon, qui a longtemps cherché à le tenir bas, l'inflation japonaise et les flux de capitaux. Il influence le yen et les placements des investisseurs japonais à l'étranger.", "liens": ["A5", "C12", "B1", "B4"], "piege": "Pas de valeur les jours fériés japonais : le trou reste un trou. Un taux bas ne signifie pas une dette sans risque. En cas de panne de la source, une moyenne mensuelle de l'OCDE (Organisation de coopération et de développement économiques) remplace la série quotidienne."},
"B11": {"titre": "Taux à 10 ans de la Chine — série non disponible", "phrase": "Cet indicateur mesurerait le rendement que demandent les investisseurs pour prêter dix ans à l'État chinois ; il n'est pas disponible ici.", "mesure": "Il refléterait le coût d'emprunt à long terme de la deuxième économie mondiale, donc ses attentes de croissance et d'inflation.", "calcul": "Ce serait un rendement déduit des prix des obligations d'État chinoises, comme pour les autres pays de cette famille.", "interpreter": "Aucun repère, faute de données. Pour suivre le crédit en Chine, voyez le taux de référence chinois (A6) et l'inflation chinoise (C13).", "bouger": "Il dépendrait de la banque centrale chinoise, de la croissance, de l'inflation et de la demande des investisseurs.", "liens": ["A6", "C13", "B1", "t:courbe"], "piege": "Aucune source gratuite, fiable et dotée d'un long historique n'a été trouvée en novembre 2026 : FRED (la base de la banque fédérale de réserve de Saint-Louis), le FMI (Fonds monétaire international), Yahoo Finance et ChinaBond ont été testés. Plutôt qu'un chiffre douteux, le tableau écrit « non disponible »."},
"B12": {"titre": "Taux à 10 ans de la Suisse", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à la Confédération suisse.", "mesure": "Le coût d'emprunt à long terme de la Suisse, valeur refuge. Il reflète la confiance des investisseurs, très forte, et le niveau des taux de la BNS (Banque nationale suisse).", "calcul": "La série vient de l'OCDE (Organisation de coopération et de développement économiques), via FRED (la base de la banque fédérale de réserve de Saint-Louis) : c'est la moyenne mensuelle des rendements des emprunts fédéraux à environ 10 ans.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles depuis 1990, il a atteint 6,924 % en juin 1992 et −0,975 % en août 2019. Il a été négatif presque sans interruption de janvier 2015 à décembre 2021.", "bouger": "La politique de la BNS, la ruée vers les valeurs refuges en temps de crise (qui le fait baisser), et les taux mondiaux. Il influence le franc suisse et les crédits en Suisse.", "liens": ["A7", "B4", "B1", "B10"], "piege": "Seulement mensuel. Un taux négatif signifie que l'investisseur paie pour prêter : ce n'est pas une erreur. Aucune source de secours n'est prévue : si l'OCDE cesse de publier la série, la courbe s'arrête."},
"B2": {"titre": "Taux à 2 ans des États-Unis — le miroir des attentes sur la Fed", "phrase": "C'est le rendement annuel que demandent les investisseurs pour prêter à l'État américain pendant deux ans.", "mesure": "Un taux à court et moyen terme, très sensible à ce que le marché attend des décisions de la Fed (Réserve fédérale, la banque centrale américaine) pour les deux années à venir.", "calcul": "Comme pour le taux à 10 ans, le Trésor américain déduit chaque jour des prix de ses obligations le rendement d'un emprunt à deux ans « à échéance constante ». Prix et rendement vont en sens inverse.", "interpreter": "Pas de seuil reconnu. Comparé au taux de la Fed : au-dessus, le marché parie plutôt sur des hausses ; en dessous, sur des baisses. Dans nos valeurs de fin de mois depuis 1990, il a atteint 8,96 % en avril 1990 et 0,11 % en juillet 2020.", "bouger": "Les propos des dirigeants de la Fed, les chiffres de l'emploi et de l'inflation. Il influence le taux des crédits à court terme, les actions sensibles aux taux et le dollar.", "liens": ["A1", "B1", "B3", "BC_10A2A"], "piege": "Il bouge plus vite que le taux à 10 ans, et un recul brutal signale souvent une crise ou l'attente de baisses de taux, pas une bonne nouvelle. Pas de valeur les jours fériés américains : le trou reste un trou."},
"B3": {"titre": "Taux à 3 mois des États-Unis — le placement sans risque à très court terme", "phrase": "C'est le rendement des bons du Trésor américain à trois mois, un placement réputé très sûr.", "mesure": "Ce que rapporte un prêt de trois mois à l'État américain. Ce taux colle de près au taux de la Fed (la banque centrale américaine) et aux décisions attendues dans les trois mois.", "calcul": "Les bons du Trésor sont vendus moins cher que leur valeur finale ; la différence fait l'intérêt. Le Trésor déduit chaque jour de leurs prix le rendement à trois mois « à échéance constante ».", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois depuis 1990, il a atteint 8,07 % en mars 1990, et 0,0 % en septembre 2015, son minimum. Il est resté sous 0,5 % à plusieurs reprises entre 2008 et 2022.", "bouger": "Presque uniquement les décisions de la Fed, attendues ou réalisées, et parfois une ruée vers les placements très sûrs. Il sert de base à l'écart avec le taux à 10 ans.", "liens": ["A1", "B1", "BC_10A3M", "B2"], "piege": "Il ne dit presque rien sur la croissance à long terme : c'est la comparaison avec le taux à 10 ans qui informe. Pas de valeur les jours fériés américains."},
"B4": {"titre": "Bund à 10 ans — le taux de référence de la zone euro", "phrase": "Le Bund (emprunt de l'État allemand) à 10 ans est le taux que paie l'Allemagne pour emprunter, repère de toute la zone euro.", "mesure": "Le coût d'emprunt à long terme de l'Allemagne, pays jugé très sûr. Les taux des autres États de la zone euro se lisent par rapport à lui.", "calcul": "La Bundesbank (la banque centrale allemande) estime chaque jour ce rendement en ajustant une courbe lisse (méthode de Svensson) sur les prix des titres fédéraux cotés : ce n'est donc pas le rendement d'un seul titre.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles depuis 1990, son maximum est de 9,23 % en septembre 1990, son minimum de −0,71 % en août 2019. Il est resté négatif de mai 2019 à janvier 2022 : l'investisseur payait pour prêter.", "bouger": "La politique de la BCE (Banque centrale européenne), l'inflation, la croissance, et la fuite vers les valeurs sûres en cas de crise (qui le fait baisser). Il influence le taux des autres États et des crédits en euros.", "liens": ["BC_IT_DE", "B5_10A", "A2", "B1", "B6"], "piege": "La série est quotidienne depuis août 1997 seulement. Avant, il n'y a qu'une valeur par mois (fin de mois) : le raccord n'est pas strictement comparable. Un taux négatif n'est pas une erreur de la série."},
"B5": {"titre": "Taux à 2 ans et à 10 ans de la zone euro — la courbe des États notés AAA de la BCE", "phrase": "Ce sont les rendements à 2 ans et à 10 ans des États de la zone euro les mieux notés, calculés par la BCE (Banque centrale européenne).", "mesure": "Ce que rapporte un prêt, à 2 ans et à 10 ans, aux États de la zone euro notés AAA (la meilleure note de solvabilité des agences de notation). C'est le taux « sans risque » de la zone euro.", "calcul": "Chaque jour, la BCE ajuste une courbe lisse (méthode de Svensson) sur les prix des obligations de ces États et en lit les taux à 2 ans et à 10 ans.", "interpreter": "Pas de seuil reconnu : on regarde l'historique depuis 2004. Dans nos valeurs de fin de mois, le 10 ans a atteint 4,73 % en juin 2008 et −0,65 % en août 2019 ; le 2 ans, 4,62 % et −0,93 %.", "bouger": "Le 2 ans suit les attentes sur la BCE ; le 10 ans reflète aussi la croissance et l'inflation attendues à long terme. Ils influencent les crédits et la bourse européenne.", "liens": ["B4", "A2", "A3", "t:courbe", "t:spread"], "piege": "Cette fiche couvre deux séries (2 ans et 10 ans). Historique depuis septembre 2004 seulement : ne pas le raccorder aux données d'avant, comme celles du Bund (emprunt de l'État allemand à 10 ans, B4). Le groupe des États AAA change avec les notes : ce n'est pas un taux moyen de tous les pays de l'euro."},
"B6": {"titre": "Taux à 10 ans de la Belgique — l'OLO", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à l'État belge, via les OLO (obligations linéaires, ses emprunts à long terme).", "mesure": "Le coût d'emprunt à long terme de la Belgique. Il reflète la confiance des investisseurs dans les finances belges et le niveau général des taux de la zone euro.", "calcul": "Eurostat (l'office statistique de l'Union européenne) publie chaque mois le rendement moyen des emprunts belges à environ 10 ans, indicateur utilisé comme « critère de convergence » pour l'euro. C'est une moyenne mensuelle.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles depuis 1990, il a atteint 10,4 % en février 1990 et −0,39 % en décembre 2020, et il a été négatif à plusieurs reprises entre août 2019 et août 2021. Le meilleur repère est son écart avec l'Allemagne.", "bouger": "La politique de la BCE (Banque centrale européenne), le Bund allemand (emprunt de l'État allemand à 10 ans, B4), la dette et le déficit belges, la note de crédit du pays. Il influence le coût de la dette publique belge.", "liens": ["BC_BE_DE", "B4", "A2", "B7"], "piege": "Seulement mensuel : n'allez pas le comparer au Bund du jour. Ce n'est pas le taux des bons d'État vendus aux particuliers. Si Eurostat est indisponible, le tableau complète avec la série de l'OCDE (Organisation de coopération et de développement économiques), de même nature."},
"B7": {"titre": "Taux à 10 ans de la France — l'OAT", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à l'État français, via les OAT (obligations assimilables du Trésor).", "mesure": "Le coût d'emprunt à long terme de la France. Il reflète la confiance des investisseurs dans les finances françaises et le niveau général des taux de la zone euro.", "calcul": "Eurostat (l'office statistique de l'Union européenne) publie chaque mois le rendement moyen des emprunts français à environ 10 ans, indicateur utilisé comme « critère de convergence » pour l'euro. C'est une moyenne mensuelle.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos données mensuelles depuis 1990, il a atteint 10,48 % en septembre 1990 et −0,34 % en août 2019, et il a été négatif à plusieurs reprises entre juillet 2019 et août 2021. Le meilleur repère est son écart avec l'Allemagne.", "bouger": "La politique de la BCE (Banque centrale européenne), le Bund allemand (emprunt de l'État allemand à 10 ans, B4), la dette et le déficit français, la politique budgétaire. Il influence le coût de la dette publique et les crédits en euros.", "liens": ["BC_FR_DE", "B4", "A2", "B6"], "piege": "Seulement mensuel : n'allez pas le comparer au taux du jour. Si Eurostat est indisponible, le tableau complète avec la série de l'OCDE (Organisation de coopération et de développement économiques), de même nature. Une hausse du taux d'un État n'annonce pas forcément une crise."},
"B8": {"titre": "Taux à 10 ans de l'Italie — le BTP", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à l'État italien, via les BTP (Buoni del Tesoro Poliennali, ses emprunts à long terme).", "mesure": "Le coût d'emprunt à long terme de l'Italie, grande économie très endettée. C'est le thermomètre habituel des tensions sur les dettes de la zone euro.", "calcul": "Eurostat (l'office statistique de l'Union européenne) publie chaque mois le rendement moyen des emprunts italiens à environ 10 ans, indicateur utilisé comme « critère de convergence » pour l'euro. C'est une moyenne mensuelle.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos moyennes mensuelles depuis 1990, il a atteint 14,42 % en octobre 1992 et 0,58 % en décembre 2020, sans jamais devenir négatif. Il se lit surtout par son écart avec l'Allemagne, qui a dépassé 3 points d'août 2011 à fin 2012.", "bouger": "Les décisions de la BCE (Banque centrale européenne), la dette publique italienne, la croissance, la politique budgétaire du gouvernement. Il influence le coût de la dette italienne et le moral des marchés européens.", "liens": ["BC_IT_DE", "B4", "A2", "B6"], "piege": "Avant l'euro (1999), le taux incluait le risque de baisse de la monnaie italienne : les niveaux d'avant ne sont pas comparables. Seulement mensuel. Un taux élevé n'annonce pas à lui seul un défaut de paiement."},
"B9": {"titre": "Taux à 10 ans du Royaume-Uni — le Gilt", "phrase": "C'est le rendement que demandent les investisseurs pour prêter dix ans à l'État britannique, via les Gilts (ses emprunts d'État).", "mesure": "Le coût d'emprunt à long terme du Royaume-Uni. Il reflète l'inflation attendue, la politique de la Banque d'Angleterre et la confiance dans les finances publiques britanniques.", "calcul": "La Banque d'Angleterre publie chaque jour le rendement « au pair nominal » à 10 ans : celui d'un emprunt fictif de dix ans émis à sa valeur nominale, estimé à partir des prix du marché.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Dans nos valeurs de fin de mois depuis novembre 1993, il a atteint 8,89 % en septembre 1994 et 0,17 % en juillet 2020. Il est resté sous 1 % de mai 2019 à août 2021.", "bouger": "Le Bank Rate (A4), l'inflation britannique, les besoins d'emprunt de l'État, les flux de capitaux. Il influence la livre sterling, les crédits immobiliers et la bourse de Londres.", "liens": ["A4", "C11", "B1", "B4"], "piege": "L'historique commence en novembre 1993. Le rendement « au pair » est une estimation, pas celui d'un titre précis. La donnée arrive avec un retard de quelques jours. En cas de panne de la source, une moyenne mensuelle de l'OCDE (Organisation de coopération et de développement économiques) la remplace."},
"BC_10A2A": {"titre": "Écart de taux 10 ans − 2 ans aux États-Unis — la pente de la courbe", "phrase": "C'est la différence entre le taux à 10 ans et le taux à 2 ans de l'État américain, exprimée en points de pourcentage.", "mesure": "La pente de la courbe des taux : les investisseurs demandent-ils plus pour prêter longtemps que pour prêter court ? Normalement oui, et l'écart est positif.", "calcul": "Taux à 10 ans moins taux à 2 ans du Trésor américain, le même jour. Par exemple, 4,5 % − 4,0 % donne 0,5 point.", "interpreter": "Au-dessus de zéro, la courbe est « normale » ; près de zéro, elle est plate ; sous zéro, elle est « inversée ». Dans nos valeurs de fin de mois depuis 1990, il est négatif en 2000, par moments entre fin 2005 et mi-2007, et de juillet 2022 à juillet 2024 (minimum de −1,06 point en juin 2023, maximum de 2,84 en janvier 2011).", "bouger": "Le 2 ans suit les attentes sur la Fed (Réserve fédérale, la banque centrale américaine) ; le 10 ans, la croissance et l'inflation à long terme. Une inversion signale que le marché attend des baisses de taux, souvent par crainte d'un ralentissement.", "liens": ["B1", "B2", "BC_10A3M", "t:courbe", "t:spread"], "piege": "Signal avancé imparfait : les inversions ont souvent précédé les récessions américaines, avec un délai variable de plusieurs mois à plus d'un an, mais ce n'est pas une règle. L'écart redevient souvent positif avant que le ralentissement ne se voie."},
"BC_10A3M": {"titre": "Écart de taux 10 ans − 3 mois aux États-Unis", "phrase": "C'est la différence entre le taux à 10 ans et le taux à 3 mois de l'État américain, exprimée en points de pourcentage.", "mesure": "La pente de la courbe des taux entre le très court et le long terme. Le taux à 3 mois suit de près la Fed (Réserve fédérale, la banque centrale américaine) ; l'écart compare donc le coût actuel de l'argent à celui des dix prochaines années.", "calcul": "Taux à 10 ans moins taux à 3 mois du Trésor américain, le même jour. Par exemple, 4,5 % − 5,0 % donne −0,5 point.", "interpreter": "Au-dessus de zéro, courbe « normale » ; sous zéro, courbe « inversée ». Dans nos valeurs de fin de mois depuis 1990, il est négatif en 2000, en 2006-2007, de mai 2019 à février 2020, de façon prolongée d'octobre 2022 à novembre 2024 (minimum de −1,88 point en mai 2023), puis brièvement en 2025. Son maximum est de 3,82 en avril 1992.", "bouger": "Surtout le taux à 3 mois, donc la politique de la Fed : quand elle monte vite ses taux, l'écart se resserre ou s'inverse. Le taux à 10 ans reflète la croissance et l'inflation à long terme.", "liens": ["B1", "B3", "BC_10A2A", "t:courbe", "A1"], "piege": "Signal avancé imparfait : une inversion a souvent précédé un ralentissement américain, avec un délai variable, mais ce n'est pas une règle. Les écarts avec le 2 ans et avec le 3 mois ne s'inversent pas toujours en même temps."},
"BC_EU": {"titre": "Écarts de taux à 10 ans — Italie, France et Belgique face à l'Allemagne", "phrase": "Ces écarts mesurent combien de points de % plus cher que l'Allemagne l'Italie, la France et la Belgique empruntent à 10 ans.", "mesure": "Le supplément de rendement exigé pour prêter à ces pays plutôt qu'à l'Allemagne, jugée la plus sûre. Plus l'écart est grand, plus le marché craint pour la dette du pays. Un point de % égale 100 points de base.", "calcul": "Taux à 10 ans du pays (Eurostat, moyenne mensuelle) moins taux à 10 ans de l'Allemagne (Eurostat, moyenne mensuelle), pour le même mois.", "interpreter": "Pas de seuil reconnu : on regarde l'historique. Pendant la crise de la dette de la zone euro, l'écart de l'Italie a dépassé 3 points d'août 2011 à fin 2012 (5,19 en novembre 2011), celui de la Belgique a atteint 2,97 et celui de la France 1,54 à ce même mois.", "bouger": "La dette et le déficit de chaque pays, la croissance, la confiance dans l'euro et les décisions de la BCE (Banque centrale européenne). Ils se creusent lors des crises.", "liens": ["BC_IT_DE", "BC_FR_DE", "BC_BE_DE", "B4", "t:spread"], "piege": "Cette fiche couvre trois séries. Elles sont mensuelles et utilisent l'Allemagne d'Eurostat, pas le Bund (emprunt allemand à 10 ans) quotidien de la Bundesbank : ne les comparez pas à l'écart du jour lu dans la presse. Avant 1999, l'écart reflète aussi le risque de change."},
"C1": {"titre": "Inflation américaine — IPC (indice des prix à la consommation), glissement annuel", "phrase": "L'IPC américain indique, en %, de combien les prix payés par les ménages des États-Unis ont augmenté en un an.", "mesure": "Le coût d'un panier type : logement, alimentation, transports, santé, loisirs. À 3 %, le même panier coûte 3 % de plus qu'il y a douze mois.", "calcul": "Le BLS (Bureau des statistiques du travail américain) publie un indice mensuel. On le compare à celui du même mois un an plus tôt. Le calcul porte sur l'indice brut, non corrigé des variations saisonnières, comme le chiffre officiel.", "interpreter": "La Fed (Réserve fédérale, la banque centrale américaine) vise 2 % par an, sur une autre mesure : le PCE (indice des prix des dépenses de consommation, C3). Depuis 1990, la moitié des mois sont sous 2,6 % et environ un mois sur dix dépasse 4,7 %. Sommet : 9,1 % en juin 2022 ; creux : −2,1 % en juillet 2009.", "bouger": "L'énergie et l'alimentation (changeantes), les loyers et les salaires (plus lents). L'IPC oriente les décisions de la Fed, donc les taux d'intérêt.", "liens": ["C2", "C3", "A1", "B1"], "piege": "L'IPC d'octobre 2025 n'a pas été publié (fermeture des services fédéraux) : pas de glissement annuel pour octobre 2025, ni pour octobre 2026 faute de base de comparaison. Ces deux trous restent vides. Autre piège : l'effet de base (le chiffre baisse si le mois d'il y a un an était très haut)."},
"C11": {"titre": "Inflation au Royaume-Uni — IPC (indice des prix à la consommation)", "phrase": "L'IPC britannique indique, en %, de combien les prix payés par les ménages du Royaume-Uni ont augmenté en un an.", "mesure": "Le coût d'un panier type de dépenses : logement, énergie, transports, alimentation, services. C'est la mesure officielle d'inflation britannique.", "calcul": "L'ONS (Office national de statistique du Royaume-Uni) calcule lui-même le glissement annuel : la hausse de l'indice par rapport au même mois un an plus tôt. Nous le reprenons tel quel.", "interpreter": "La Banque d'Angleterre vise 2 %. Depuis 1990, la moitié des mois sont sous 2,3 % et environ un mois sur dix dépasse 5,9 %. Sommet : 11,1 % en octobre 2022, plus haut que la zone euro (10,6 %). Creux : −0,1 % en avril 2015 : l'inflation y est très rarement négative.", "bouger": "L'énergie, l'alimentation, les loyers et les salaires. Elle guide les taux de la Banque d'Angleterre (A4), donc les prêts hypothécaires et le cours de la livre sterling.", "liens": ["A4", "B9", "C5", "E1_UK"], "piege": "Ne pas la comparer à l'IPCH (indice des prix à la consommation harmonisé) de la zone euro sans précaution : le panier et les pondérations diffèrent. Les données d'autres fournisseurs (OCDE) peuvent s'écarter de l'ONS ; on retient ici l'ONS. La série démarre en 1990."},
"C12": {"titre": "Inflation au Japon — IPC (indice des prix à la consommation)", "phrase": "L'IPC japonais indique, en %, de combien les prix payés par les ménages du Japon ont augmenté en un an.", "mesure": "Le coût d'un panier type de dépenses des ménages japonais. Le Japon est connu pour des prix longtemps stagnants, voire en baisse (déflation) : les données le confirment.", "calcul": "On part de l'indice mensuel des prix diffusé par le FMI (Fonds monétaire international), qui reprend les chiffres du Japon, et on le compare à celui du même mois un an plus tôt. Le FMI donne l'indice avec une seule décimale : l'écart avec le chiffre officiel peut atteindre 0,1 point.", "interpreter": "Depuis 1990, 36 % des mois sont négatifs et la moitié sont sous 0,3 %. Le plus haut est de 4,4 % en janvier 2023 ; le plus bas, −2,5 % en octobre 2009. La Banque du Japon vise 2 %.", "bouger": "Les prix de l'énergie importée, la faiblesse ou la force du yen, les salaires et les hausses de taxes. L'inflation guide la politique de la Banque du Japon (A5).", "liens": ["A5", "B10", "C13", "E1_JP"], "piege": "La série arrive avec environ un mois de retard sur les autres. Une hausse de taxe peut gonfler l'indice pendant douze mois (ainsi d'avril 2014 à mars 2015) sans refléter de vraie surchauffe."},
"C13": {"titre": "Inflation en Chine — IPC (indice des prix à la consommation)", "phrase": "L'IPC chinois indique, en %, de combien les prix payés par les ménages de Chine ont augmenté en un an.", "mesure": "Le coût d'un panier type de dépenses des ménages chinois. L'origine des données est le Bureau national des statistiques de Chine.", "calcul": "L'OCDE (Organisation de coopération et de développement économiques) reprend et diffuse le glissement annuel, c'est-à-dire la hausse par rapport au même mois un an plus tôt. Le FMI (Fonds monétaire international) publie une série voisine, qui s'écarte parfois de plus de 0,3 point.", "interpreter": "La moitié des mois depuis 1990 sont sous 1,9 %, mais le haut de la série est tiré par les années 1990 : le record est de 27,7 % en octobre 1994. Des mois négatifs apparaissent en 1998-2002, en 2009, en 2020-2021 et de 2023 à 2025 : on parle alors de déflation.", "bouger": "L'alimentation, la demande intérieure et l'activité économique. Il reflète l'état de la consommation chinoise.", "liens": ["A6", "E1_CN", "C12", "B11"], "piege": "Le percentile « depuis 1990 » compare à une époque où la Chine connaissait une forte inflation : un chiffre actuel peut sembler faible sans l'être pour la période récente. L'OCDE et le FMI divergent parfois : la série retenue est celle de l'OCDE."},
"C2": {"titre": "Inflation sous-jacente américaine — IPC hors énergie et alimentation", "phrase": "L'inflation sous-jacente retire l'énergie et l'alimentation pour mieux voir la tendance de fond des prix aux États-Unis.", "mesure": "La hausse sur un an des prix du reste du panier : logement, voitures, vêtements, services médicaux. L'énergie et l'alimentation varient beaucoup d'un mois à l'autre ; les écarter donne une lecture plus stable.", "calcul": "Même méthode que l'IPC (indice des prix à la consommation, C1) du BLS (Bureau des statistiques du travail américain) : indice brut, non corrigé des variations saisonnières, comparé à celui du même mois un an plus tôt.", "interpreter": "Depuis 1990, la moitié des mois sont sous 2,3 %, un sur quatre dépasse 2,9 % et un sur dix 4,4 %. Sommet : 6,6 % en septembre 2022. Si elle reste haute pendant que l'IPC total retombe, la Fed (banque centrale américaine) y voit le signe d'une inflation installée.", "bouger": "Les loyers, les salaires et les prix des services, qui s'ajustent lentement. Elle pèse sur les décisions de la Fed, donc sur les taux.", "liens": ["C1", "C4", "D11", "A1"], "piege": "Même trou que C1 : l'indice d'octobre 2025 n'a pas été publié (fermeture des services fédéraux), donc pas de glissement annuel pour octobre 2025 ni octobre 2026. « Sous-jacente » ne veut pas dire « sans importance » : l'énergie pèse dans le budget des ménages."},
"C3": {"titre": "Inflation américaine — PCE (indice des dépenses de consommation), la mesure visée par la Fed", "phrase": "Le PCE mesure la hausse des prix des dépenses de consommation américaines ; c'est l'indicateur d'inflation que la Fed (Réserve fédérale, la banque centrale américaine) regarde en priorité.", "mesure": "La hausse sur un an des prix de tout ce que consomment les ménages, y compris des dépenses réglées en leur nom, comme une partie des soins de santé. Son champ est plus large que celui de l'IPC (indice des prix à la consommation, C1).", "calcul": "Le BEA (Bureau d'analyse économique américain) publie un indice mensuel. On le compare à celui du même mois un an plus tôt. Il paraît un peu après l'IPC.", "interpreter": "La Fed vise 2 % par an sur cette mesure. Depuis 1990, la moitié des mois sont sous 2,2 % (contre 2,6 % pour l'IPC) : le PCE est le plus souvent plus bas que l'IPC. Sommet : 7,2 % en juin 2022 ; creux : −1,5 % en juillet 2009.", "bouger": "Les mêmes forces que l'IPC (énergie, loyers, salaires), avec plus de poids pour la santé. Il guide la politique de la Fed, donc les taux d'intérêt.", "liens": ["C4", "C1", "A1", "B2"], "piege": "L'objectif de 2 % vise le PCE, pas l'IPC : comparer l'IPC à 2 % donne une impression trompeuse. L'indice utilisé est corrigé des variations saisonnières. Contrairement à l'IPC, octobre 2025 est présent : aucun trou."},
"C4": {"titre": "Inflation sous-jacente américaine — PCE hors énergie et alimentation", "phrase": "Le PCE (indice des prix des dépenses de consommation) sous-jacent est l'inflation que la Fed (Réserve fédérale, la banque centrale américaine) surveille de plus près pour juger de la tendance de fond.", "mesure": "La hausse sur un an des prix des dépenses de consommation (PCE, voir C3), une fois retirés l'énergie et l'alimentation, dont les prix sautent d'un mois à l'autre.", "calcul": "Le BEA (Bureau d'analyse économique américain) publie l'indice mensuel. On le compare à celui du même mois un an plus tôt. Il paraît un peu après l'IPC (indice des prix à la consommation).", "interpreter": "La Fed vise 2 % par an sur le PCE total. Pour le PCE sous-jacent, la moitié des mois depuis 1990 sont sous 1,9 % ; environ un mois sur dix dépasse 3,5 %. Sommet : 5,6 % en septembre 2022 ; creux : 0,6 % en juillet 2009.", "bouger": "Les loyers, les salaires et les prix des services, qui évoluent lentement. Il sert de repère aux décisions de la Fed, donc aux taux d'intérêt.", "liens": ["C3", "C2", "A1", "D11"], "piege": "Ne pas le confondre avec l'IPC sous-jacent (C2) : le champ et les pondérations diffèrent, donc les chiffres aussi. L'indice est corrigé des variations saisonnières. Pas de trou en octobre 2025."},
"C5": {"titre": "Inflation en zone euro — IPCH (indice des prix à la consommation harmonisé)", "phrase": "L'IPCH de la zone euro indique, en %, de combien les prix payés par les ménages de l'ensemble de la zone ont augmenté en un an.", "mesure": "Le coût d'un panier type de dépenses, avec les mêmes règles dans tous les pays de l'euro. C'est la mesure officielle d'inflation de la zone.", "calcul": "Les instituts de statistique nationaux relèvent les prix. Eurostat (l'office statistique européen) les agrège, et la BCE (Banque centrale européenne) diffuse le glissement annuel, c'est-à-dire la hausse par rapport au même mois un an plus tôt.", "interpreter": "La BCE vise 2 % à moyen terme. Depuis 1997, la moitié des mois sont sous 1,9 %, trois mois sur quatre sous 2,4 % et neuf sur dix sous 3,2 %. Sommet : 10,6 % en octobre 2022 ; creux : −0,7 % en juillet 2009.", "bouger": "Prix de l'énergie et de l'alimentation, salaires, demande. L'inflation guide les taux de la BCE (A2), donc les prêts, l'épargne et les obligations.", "liens": ["C6", "C7", "A2", "D5_LT", "H1"], "piege": "L'historique commence en 1997 (début de l'IPCH). Depuis février 2026, la méthode change (nouvelle nomenclature des produits) ; l'historique 1997-2025 a été republié avec des écarts d'au plus 0,1 point. La zone s'élargit avec le temps : le contenu n'est pas le même en 1997 qu'aujourd'hui."},
"C6": {"titre": "Inflation sous-jacente de la zone euro — IPCH hors énergie, alimentation, alcool et tabac", "phrase": "L'inflation sous-jacente de la zone euro écarte les prix les plus changeants pour révéler la tendance de fond.", "mesure": "La hausse sur un an des prix des biens et services, hors énergie, alimentation, alcool et tabac. Elle reste donc surtout liée aux salaires et aux services.", "calcul": "On part de l'IPCH (indice des prix à la consommation harmonisé, C5), publié par la BCE (Banque centrale européenne) : indice moins les postes cités, comparé à celui du même mois un an plus tôt.", "interpreter": "Depuis 1997, la moitié des mois sont sous 1,3 % et un mois sur dix dépasse 2,7 %. Elle n'est jamais passée sous zéro sur cette période. Sommet : 5,7 % en mars 2023, soit cinq mois après le pic de l'inflation totale (octobre 2022) ; creux : 0,2 % en septembre 2020.", "bouger": "Les salaires, les loyers et les services, qui réagissent lentement. La BCE la suit de près pour décider de ses taux.", "liens": ["C5", "D12", "A2", "C7"], "piege": "Elle redescend plus lentement que l'inflation totale : une baisse de C5 ne suffit pas à conclure que le problème est réglé. Historique depuis 1997 seulement, et méthode de l'IPCH modifiée en février 2026 (écarts d'au plus 0,1 point sur le passé)."},
"C7": {"titre": "Inflation en Belgique — IPCH (indice des prix à la consommation harmonisé)", "phrase": "L'IPCH belge mesure, en %, la hausse sur un an des prix payés par les ménages belges, selon les règles communes à la zone euro.", "mesure": "Le coût d'un panier type de dépenses en Belgique, calculé comme dans les autres pays de l'euro. Cela permet de comparer avec la France, l'Allemagne ou l'ensemble de la zone.", "calcul": "Les statisticiens belges relèvent les prix ; la BCE (Banque centrale européenne) diffuse l'indice harmonisé et sa hausse par rapport au même mois un an plus tôt.", "interpreter": "Depuis 1997, la moitié des mois sont sous 2,0 % et environ un mois sur dix dépasse 4,4 %. Le sommet, 13,1 % en octobre 2022, dépasse celui de la zone euro (10,6 %). Creux : −1,7 % en juillet 2009.", "bouger": "Surtout les prix de l'énergie, de l'alimentation et des services. Il permet de situer la Belgique par rapport à ses voisins et à la zone euro.", "liens": ["C5", "C8", "C6", "A2"], "piege": "L'IPCH n'est pas l'indice national belge utilisé pour l'indexation des salaires et de certains loyers : les chiffres diffèrent. L'historique commence en 1997 ; la méthode de l'IPCH a changé en février 2026."},
"C8": {"titre": "Inflation en Allemagne, en France et en Italie — IPCH (indice des prix à la consommation harmonisé)", "phrase": "Ces trois courbes mesurent, en %, la hausse sur un an des prix payés par les ménages des trois plus grandes économies de la zone euro.", "mesure": "Le coût d'un panier type de dépenses dans chaque pays, selon des règles identiques : on peut donc les comparer entre elles et avec la zone euro (C5).", "calcul": "Les instituts nationaux relèvent les prix ; la BCE (Banque centrale européenne) diffuse l'indice harmonisé et sa hausse par rapport au même mois un an plus tôt.", "interpreter": "Depuis 1997, la moitié des mois sont sous 1,7 % en Allemagne, 1,6 % en France et 1,9 % en Italie. Sommets : Italie 12,6 % et Allemagne 11,6 % en octobre 2022 ; France 7,3 % en février 2023, nettement plus bas. Creux : environ −0,7 à −0,8 % en juillet 2009 (Allemagne, France), −1,1 % en septembre 2020 (Italie).", "bouger": "Énergie, alimentation et salaires, avec des écarts d'un pays à l'autre. Ces écarts compliquent la tâche de la BCE, qui fixe un seul taux pour tous.", "liens": ["C5", "C7", "C6", "BC_IT_DE"], "piege": "Un seul taux directeur pour trois pays dont l'inflation diffère : il convient rarement aux trois à la fois. Historique depuis 1997 (début de l'IPCH) ; méthode de l'IPCH modifiée en février 2026."},
"D1": {"titre": "Inflation anticipée à 5 ans aux États-Unis — « point mort d'inflation »", "phrase": "Le point mort à 5 ans indique l'inflation annuelle moyenne que les marchés financiers anticipent aux États-Unis sur les cinq prochaines années.", "mesure": "Ce que les investisseurs en obligations d'État américaines s'attendent à voir comme inflation moyenne par an sur cinq ans, d'après les prix qu'ils paient.", "calcul": "C'est l'écart entre le rendement d'une obligation d'État à 5 ans ordinaire et celui d'une obligation à 5 ans protégée contre l'inflation (TIPS, Treasury Inflation-Protected Securities). Cette différence correspond à l'inflation que le marché juge « payée d'avance ».", "interpreter": "Depuis 2003, la moitié des mois sont sous 2,0 % et 80 % des mois se situent entre 1,3 et 2,6 % environ. Un niveau stable, autour de 2 à 2,5 %, signale des anticipations calmes. Extrêmes en fin de mois : −2,2 % en novembre 2008 (crise financière) et 3,3 % en mars 2022.", "bouger": "Les prix du pétrole, l'inflation récente et la politique de la Fed (banque centrale américaine). Il influence le coût de l'argent à moyen terme.", "liens": ["D2", "D3", "C1", "t:point_mort"], "piege": "Ce n'est pas une prévision certaine : il mélange l'inflation attendue, une prime de risque et la liquidité du marché (d'où les valeurs aberrantes de 2008). Série quotidienne depuis 2003 ; les jours fériés restent vides. Les TIPS suivent l'IPC (indice des prix à la consommation, C1), pas le PCE (indice des prix des dépenses de consommation, C3)."},
"D10": {"titre": "Indice des tensions sur les chaînes d'approvisionnement mondiales — GSCPI (Global Supply Chain Pressure Index)", "phrase": "Cet indice indique si le commerce mondial fonctionne plus mal ou mieux que d'habitude : retards de livraison, goulots d'étranglement.", "mesure": "Le niveau de tension des chaînes d'approvisionnement mondiales. 0 correspond à la moyenne de la période ; chaque unité vaut un écart-type, c'est-à-dire un écart « typique » par rapport à cette moyenne.", "calcul": "La Fed (banque centrale américaine) de New York combine des coûts de transport et des enquêtes auprès des directeurs d'achat de plusieurs économies (délais, stocks, commandes en retard) en un seul chiffre mensuel.", "interpreter": "Depuis 1998, la moitié des mois sont sous −0,25 et un mois sur dix dépasse 1,2. Avant 2020, le maximum n'atteignait pas 1,6 (avril 2011). Le sommet est de 4,4 en décembre 2021 ; le creux de −1,6 en mai 2023.", "bouger": "Les confinements, la congestion des ports, les coûts du fret, les guerres. Des tensions élevées poussent les prix à la production (D8) puis l'inflation (C1).", "liens": ["D8", "D9", "C1", "C5"], "piege": "L'indice est centré (0 = normal), pas en base 100 : un chiffre négatif signifie des chaînes plus fluides que la moyenne. Il peut être révisé après publication."},
"D11": {"titre": "Salaire horaire moyen aux États-Unis, glissement annuel", "phrase": "Cet indicateur indique de combien le salaire horaire moyen des travailleurs américains a augmenté en un an.", "mesure": "Le salaire moyen par heure travaillée de l'ensemble des salariés du secteur privé. Les salaires nourrissent les prix des services : leur hausse pèse sur l'inflation.", "calcul": "Le BLS (Bureau des statistiques du travail américain) publie le salaire moyen en dollars chaque mois. On calcule la hausse par rapport au même mois un an plus tôt.", "interpreter": "Depuis 2007, la moitié des mois sont sous 3,0 % ; trois mois sur quatre sont sous 3,9 %. Un salaire qui progresse plus vite que les prix augmente le pouvoir d'achat, mais peut entretenir l'inflation des services.", "bouger": "L'état du marché du travail : plus il y a de pénurie de main-d'œuvre, plus les salaires montent. Il influence l'inflation sous-jacente (C2) et la Fed (banque centrale américaine).", "liens": ["C2", "C1", "D12", "A1"], "piege": "Historique court : depuis mars 2007. Cette moyenne peut être faussée quand la composition des emplois change : au printemps 2020, les emplois peu payés ont disparu en premier et le chiffre a atteint 8,1 % (avril 2020), puis 0,6 % un an plus tard."},
"D12": {"titre": "Salaires négociés dans la zone euro, glissement annuel", "phrase": "Cet indicateur indique de combien ont augmenté en un an les salaires fixés par les accords collectifs en zone euro.", "mesure": "La progression des salaires prévue dans les conventions collectives. C'est ce que la BCE (Banque centrale européenne) regarde pour savoir si la hausse des salaires menace de relancer l'inflation.", "calcul": "La BCE réunit les accords de chaque pays et publie la hausse par rapport au même trimestre un an plus tôt. La série est trimestrielle.", "interpreter": "Depuis 1991, la moitié des trimestres sont sous 2,2 % et neuf sur dix sous 4,4 %. Après 2020, le plus haut est de 5,5 % au troisième trimestre 2024.", "bouger": "L'inflation passée (les salariés rattrapent les prix), la situation du marché du travail et le calendrier des accords. Il influence l'inflation sous-jacente (C6).", "liens": ["C6", "C5", "D11", "A2"], "piege": "La série est irrégulière : des primes uniques ou le calendrier des accords peuvent la faire sauter d'un trimestre à l'autre. Elle suit la zone euro à composition variable. Elle ne mesure que les accords négociés, pas les salaires réellement versés."},
"D13": {"titre": "Indicateurs avancés de l'OCDE (CLI) — États-Unis, Chine, Japon, Royaume-Uni, Allemagne et quatre grandes économies européennes", "phrase": "Le CLI (Composite Leading Indicator, indicateur composite avancé) tente de signaler, quelques mois à l'avance, si l'activité économique d'un pays va accélérer ou ralentir.", "mesure": "L'OCDE (Organisation de coopération et de développement économiques) combine des signaux qui précèdent la conjoncture, par exemple commandes, confiance des entreprises et marchés financiers. 100 correspond à la tendance de long terme de l'économie.", "calcul": "Chaque pays a son indice, publié chaque mois. Les « 4 grandes économies européennes » forment un agrégat de l'OCDE (Allemagne, France, Italie, Royaume-Uni).", "interpreter": "Au-dessus de 100 et en hausse : activité plus rapide que sa tendance. Au-dessous de 100 et en baisse : ralentissement. Selon le pays, la série passe sous 100 entre 37 % et 56 % du temps. Plus bas d'avril 2020 : États-Unis 92,9, Royaume-Uni 87,0, Allemagne 90,8. Japon : creux en mars 2009 (96,3).", "bouger": "La confiance des entreprises, les commandes, le crédit et les marchés financiers. Il annonce souvent les virages de la croissance.", "liens": ["E1_US", "E1_CN", "E1_JP", "D14"], "piege": "Zone euro non disponible : l'OCDE ne publie plus cet indicateur pour elle. On affiche donc l'Allemagne et l'agrégat de 4 grandes économies européennes, qui contient le Royaume-Uni (hors zone euro). Les données sont révisées souvent. Chine : début en mai 1992."},
"D14": {"titre": "Probabilité de récession aux États-Unis dans 12 mois — modèle de la Fed de New York", "phrase": "Ce chiffre donne la probabilité, selon la courbe des taux, que les États-Unis soient en récession dans un an.", "mesure": "La probabilité d'une récession (recul de l'activité) 12 mois après le calcul. Le modèle repose sur un seul signal : l'écart entre le taux à 10 ans et le taux à 3 mois des bons du Trésor américain.", "calcul": "P = Φ(−0,5333 − 0,6330 × écart), où Φ désigne la loi normale cumulée (courbe en cloche) et l'écart, en points, est le taux à 10 ans moins celui à 3 mois. Écart nul : environ 30 % ; +1 point : 12 % ; −1 point (courbe inversée) : 54 %.", "interpreter": "Depuis 1990, la probabilité médiane est de 7 % ; elle dépasse 19,6 % un mois sur quatre et 31,6 % un mois sur dix. Record : 70,9 % (écart de mai 2023). Dépasser 50 % demande une courbe inversée d'au moins 0,84 point.", "bouger": "Les décisions de la Fed (Réserve fédérale, banque centrale américaine) sur les taux courts et les attentes de croissance et d'inflation (taux longs). Une courbe inversée précède historiquement les récessions.", "liens": ["BC_10A3M", "B1", "B3", "A1"], "piege": "Modèle à une seule variable : une probabilité élevée n'est pas une certitude et ne dit pas quand. Le modèle a affiché plus de 50 % pendant une vingtaine de mois entre janvier 2023 et septembre 2024. Ne pas confondre le mois de l'écart (indiqué ici, datation de la valeur) et le mois visé (12 mois plus tard)."},
"D15": {"titre": "Courbe à terme du pétrole Brent — prix attendus dans 6 et 12 mois", "phrase": "La courbe à terme du Brent montre à quel prix le pétrole s'échange aujourd'hui pour être livré dans les mois qui viennent.", "mesure": "Les prix des contrats à terme (accords d'achat ou de vente à un prix fixé aujourd'hui, pour une livraison future) sur le baril de Brent, mois par mois. On retient les échéances à environ 6 et 12 mois, comparées au contrat le plus proche.", "calcul": "Les cours viennent de Yahoo Finance, pour les contrats du NYMEX (New York Mercantile Exchange). Ces contrats expirent : on recalcule chaque jour les échéances à prendre. Prix en dollars par baril, à la dernière clôture.", "interpreter": "Si les prix lointains sont plus bas que le prix proche, la courbe est en « backwardation » : le marché valorise la livraison immédiate. S'ils sont plus hauts, elle est en « contango », souvent lié à des stocks abondants.", "bouger": "Les stocks, la production, les tensions géopolitiques et la demande mondiale. Elle influence les anticipations d'inflation (D1).", "liens": ["H1", "C5", "D1", "t:future"], "piege": "Ce n'est pas une prévision du prix futur, mais le prix auquel on peut s'engager aujourd'hui. Données Yahoo d'usage personnel : certains mois lointains manquent parfois, et un contrat qui expire le jour même garde son dernier cours. Aucun prix n'est reconstitué."},
"D2": {"titre": "Inflation anticipée à 10 ans aux États-Unis — « point mort d'inflation »", "phrase": "Le point mort à 10 ans indique l'inflation annuelle moyenne que les marchés anticipent aux États-Unis sur la prochaine décennie.", "mesure": "L'inflation moyenne par an sur dix ans que les investisseurs en obligations d'État américaines semblent attendre, d'après les prix qu'ils paient.", "calcul": "Écart entre le rendement d'une obligation d'État à 10 ans ordinaire et celui d'une obligation à 10 ans protégée contre l'inflation (TIPS, Treasury Inflation-Protected Securities).", "interpreter": "Depuis 2003, la moitié des mois sont sous 2,2 % et 80 % se situent entre 1,6 et 2,5 % environ. Un niveau stable autour de 2 à 2,5 % indique que les marchés croient la Fed (banque centrale américaine) capable de maîtriser les prix. Extrêmes en fin de mois : 0,1 % en décembre 2008 et 2,9 % en avril 2022.", "bouger": "L'inflation récente, le pétrole et la crédibilité de la Fed. Plus long que D1, il bouge moins : il reflète davantage la confiance à long terme.", "liens": ["D1", "D3", "B1", "C1"], "piege": "Comme D1, c'est un prix de marché, pas un pronostic : prime de risque et liquidité y sont mêlées. La série démarre en 2003 ; les jours fériés restent vides. Les TIPS suivent l'IPC (indice des prix à la consommation, C1), pas le PCE (indice des prix des dépenses de consommation, C3)."},
"D3": {"titre": "Inflation anticipée « 5 ans dans 5 ans » aux États-Unis", "phrase": "Cet indicateur donne l'inflation annuelle que les marchés anticipent aux États-Unis pour les années 6 à 10 à partir d'aujourd'hui.", "mesure": "L'inflation moyenne par an attendue entre dans cinq ans et dans dix ans. Il écarte donc les chocs du moment (pétrole, crise) pour ne garder que l'ancrage à long terme.", "calcul": "On le déduit des points morts à 5 ans (D1) et à 10 ans (D2), tous deux tirés des obligations protégées contre l'inflation (TIPS, Treasury Inflation-Protected Securities). Approximation : 2 fois le point mort à 10 ans, moins celui à 5 ans.", "interpreter": "Depuis 2003, la moitié des mois sont sous 2,3 % et 80 % se situent entre 1,8 et 2,6 % environ. La Fed (banque centrale américaine) y lit si le public croit encore à son objectif de 2 %. En novembre 2008, il a atteint 3,0 % puis chuté à 0,5 % le mois suivant (valeurs de fin de mois).", "bouger": "Les doutes sur la crédibilité de la Fed et une inflation récente persistante. Il bouge nettement moins que D1.", "liens": ["D1", "D2", "C1", "t:point_mort"], "piege": "Un calcul dérivé de deux autres séries : les erreurs s'additionnent. Les écarts de 2008 sont dus aux tensions du marché, non à l'inflation. Série démarrant en 2003, jours fériés vides."},
"D4": {"titre": "Inflation attendue par les ménages américains — enquête de l'Université du Michigan", "phrase": "Cette enquête mesure l'inflation que les ménages américains s'attendent à subir dans les 12 prochains mois.", "mesure": "On demande chaque mois à un échantillon d'Américains de combien les prix augmenteront selon eux d'ici un an. La série retient la réponse médiane, celle du milieu.", "calcul": "Pas de formule de marché : c'est une enquête (Surveys of Consumers, Université du Michigan). La réponse médiane est publiée telle quelle, en % par an.", "interpreter": "Depuis 1990, la moitié des mois sont sous 3,0 % (médiane de l'IPC, indice des prix à la consommation, sur la même période : 2,6 %) ; 80 % se situent entre 2,5 et 4,5 % environ. Le record est de 6,6 % en mai 2025, au-dessus du pic de 2022 (5,4 %).", "bouger": "Les prix visibles au quotidien (alimentation, carburant), l'actualité économique et politique. La Fed (banque centrale américaine) les surveille : des anticipations qui s'envolent peuvent entretenir l'inflation.", "liens": ["C1", "D1", "D2", "A1"], "piege": "C'est un sentiment, pas un prix de marché : il réagit vite aux humeurs et à l'actualité politique. Droits d'auteur de l'Université du Michigan : la source doit être citée. Pas de trou en octobre 2025."},
"D5": {"titre": "Enquête de la BCE auprès des prévisionnistes professionnels (SPF) — probabilités d'inflation et inflation à long terme", "phrase": "Chaque trimestre, la BCE (Banque centrale européenne) demande à des économistes (enquête SPF, Survey of Professional Forecasters) quelle inflation ils attendent et quelle probabilité ils donnent à chaque scénario.", "mesure": "Elle interroge une cinquantaine de prévisionnistes. Pour l'année en cours, les deux suivantes et le long terme (cinq ans plus tard), chacun répartit 100 % entre des tranches d'inflation de 0,5 point. On affiche la moyenne de ces réponses.", "calcul": "On moyenne les réponses. Les tranches vont de « moins de −0,8 % » à « 4,8 % et plus ». L'inflation attendue est la moyenne des prévisions chiffrées, pour l'IPCH (indice des prix à la consommation harmonisé, C5).", "interpreter": "Ce qui compte : où se concentre la probabilité, et quelle part dépasse 2 %, l'objectif de la BCE. Pour le long terme, depuis 1999, la moitié des enquêtes sont sous 1,9 % et toutes sous 2,2 %. Creux : 1,65 % (3ᵉ trimestre 2020) ; sommet : 2,18 % (4ᵉ trimestre 2022).", "bouger": "Le choc d'énergie du moment pèse surtout sur les années proches ; le long terme bouge peu tant que la BCE reste crédible.", "liens": ["C5", "C6", "A2", "D1"], "piege": "Ce sont des probabilités moyennes, pas des fréquences constatées. La tranche « 1,8 à 2,2 % » encadre le seuil de 2 % sans dire de quel côté. Avant 2001, le long terme n'a qu'un point par an ; les tranches ont changé au fil du temps."},
"D6": {"titre": "Enquête de la Fed de Philadelphie auprès des prévisionnistes (SPF) — probabilités d'inflation sous-jacente", "phrase": "Cette enquête (SPF, Survey of Professional Forecasters) indique la probabilité que des économistes américains donnent à chaque niveau d'inflation sous-jacente pour l'année en cours et la suivante.", "mesure": "Chaque trimestre, la Fed de Philadelphie (une banque de la Réserve fédérale, la banque centrale américaine) demande aux prévisionnistes de répartir 100 % entre dix tranches d'inflation sous-jacente (IPC, indice des prix à la consommation, hors énergie et alimentation, C2), de « moins de 0 % » à « 4,0 % ou plus ». L'IPC total n'est pas suivi ici.", "calcul": "On moyenne les répartitions des répondants. L'inflation est mesurée du quatrième trimestre d'une année au quatrième trimestre suivant. Les tranches font 0,5 point de large.", "interpreter": "Regarder où se concentre la probabilité et si elle est étalée : une distribution étroite signale un consensus. « Sous 2 % » additionne les tranches de moins de 2,0 % ; la tranche « 2,0 à 2,4 % » est déjà au-dessus. Pas de repère historique chiffré : la série est courte (depuis 2007).", "bouger": "L'inflation observée, le marché du travail et les décisions de la Fed. Les prévisions se révisent beaucoup quand l'inflation surprend.", "liens": ["C2", "C4", "D4", "D1"], "piege": "Historique court : depuis le 1ᵉʳ trimestre 2007 seulement. L'enquête porte sur l'IPC sous-jacent alors que la Fed vise 2 % sur le PCE (indice des prix des dépenses de consommation) : ne pas comparer directement ces probabilités à son objectif."},
"D7": {"titre": "Prévisions d'inflation du FMI — Perspectives de l'économie mondiale", "phrase": "Le FMI (Fonds monétaire international) publie, pour chaque pays, l'inflation qu'il attend pour l'année en cours et les suivantes.", "mesure": "Il prévoit l'évolution moyenne annuelle des prix à la consommation pour les États-Unis, la zone euro, la Belgique, l'Allemagne, la France, l'Italie, le Japon, la Chine et le Royaume-Uni.", "calcul": "Ses économistes combinent données récentes et hypothèses (prix du pétrole, croissance, politiques économiques). Les chiffres sont publiés deux fois par an (avril et octobre). On affiche la dernière édition.", "interpreter": "Comparer la prévision à l'objectif de la banque centrale (souvent 2 %) et à l'inflation récente : si la prévision redescend vers 2 % en deux ou trois ans, le FMI attend un retour à la normale.", "bouger": "Le prix du pétrole et de l'énergie, la croissance et les salaires. Les prévisions sont révisées à chaque édition, surtout après un choc.", "liens": ["C1", "C5", "C12", "D5_LT"], "piege": "Les chiffres sont des moyennes annuelles : ils ne se comparent pas directement au dernier glissement mensuel. Ce sont des prévisions, corrigées à chaque édition ; on n'affiche que la dernière. Source à usage non commercial, citation obligatoire."},
"D8": {"titre": "Prix à la production aux États-Unis — PPI (Producer Price Index), glissement annuel", "phrase": "Cet indicateur mesure de combien ont augmenté en un an les prix auxquels les producteurs américains vendent leurs marchandises.", "mesure": "Les prix à la sortie de l'usine ou de la ferme, avant la marge des commerçants. Il porte sur les biens (matières, produits intermédiaires, produits finis), pas sur les services.", "calcul": "Le BLS (Bureau des statistiques du travail américain) publie un indice mensuel. On calcule ici la hausse par rapport au même mois un an plus tôt.", "interpreter": "Depuis 1990, la moitié des mois sont sous 2,2 % environ, un mois sur quatre dépasse 5,4 % et un sur dix dépasse 9,0 %. Extrêmes : 22,7 % en novembre 2021 ; −16,1 % en juillet 2009. Des écarts de cette ampleur ne sont pas rares.", "bouger": "Surtout les prix de l'énergie et des matières premières. Il précède souvent l'inflation des consommateurs (C1), mais de façon irrégulière.", "liens": ["C1", "D9", "H1", "D10"], "piege": "Il est bien plus volatil que l'IPC (indice des prix à la consommation) et ne se répercute pas toujours sur les prix aux consommateurs : les entreprises absorbent une partie de la hausse dans leur marge."},
"D9": {"titre": "Prix à la production industrielle dans la zone euro, glissement annuel", "phrase": "Cet indicateur mesure de combien ont augmenté en un an les prix auxquels les industriels de la zone euro vendent sur leur marché national.", "mesure": "Les prix de vente à la sortie de l'usine, énergie incluse, pour l'industrie hors construction. C'est un signal avancé : ces prix se retrouvent plus tard dans les rayons.", "calcul": "Eurostat (l'office statistique européen) publie directement la hausse par rapport au même mois un an plus tôt, pour la zone euro à 20 pays.", "interpreter": "Depuis 1996, la moitié des mois sont sous 1,3 %, un mois sur dix sous −3,0 % et un autre sur dix au-dessus de 6,0 %. Extrêmes : 40,1 % en août 2022 ; −10,0 % en septembre 2023 (retour des prix de l'énergie).", "bouger": "L'énergie (gaz, électricité, pétrole) et les matières premières. Il influence l'inflation des consommateurs (C5) avec quelques mois de décalage.", "liens": ["C5", "D8", "H4", "D10"], "piege": "Les prix de l'énergie dominent : le chiffre peut bondir ou plonger sans que l'inflation de fond (C6) change. Série suivant la zone euro à 20 pays, sans la Bulgarie. Historique depuis 1996."},
"DC": {"titre": "Anticipation des taux directeurs de la Fed et de la BCE — taux à 2 ans moins taux directeur", "phrase": "Cet écart montre si les marchés s'attendent à ce que la banque centrale baisse ou relève ses taux dans les deux prochaines années.", "mesure": "La différence, en points, entre le taux d'un emprunt d'État à 2 ans et le taux directeur actuel : celui de la Fed (banque centrale américaine) ou le taux de dépôt de la BCE (Banque centrale européenne).", "calcul": "Fed : taux des emprunts d'État américains à 2 ans moins taux effectif des fonds fédéraux. BCE : taux à 2 ans des États de la zone euro notés AAA (la meilleure note) moins taux de dépôt de la BCE.", "interpreter": "Sous −0,25 point : le marché anticipe des baisses. Au-dessus de +0,25 : des hausses. Entre les deux : stabilité. Dans nos valeurs de fin de mois depuis 1990, la Fed a été en « hausses anticipées » 52 % des mois et en « baisses anticipées » 20 % ; pour la BCE, depuis 2004, 38 % et 23 %. Extrêmes mensuels : Fed −1,84 (septembre 1998) et +2,75 (décembre 1994).", "bouger": "Les chiffres d'inflation et d'emploi, et les discours des banquiers centraux. Il précède souvent le changement réel de taux.", "liens": ["B2", "A1", "B5_2A", "A2"], "piege": "Un taux à 2 ans n'est pas une prévision sûre : il contient aussi une prime de risque. La courbe AAA de la BCE ne couvre que les États les mieux notés et commence en septembre 2004 (celle de la Fed : 1990)."},
"E1": {"titre": "PIB réel — la croissance de l'économie (glissement annuel)", "phrase": "Cette série indique de combien l'économie d'un pays a grandi, en volume, par rapport au même trimestre un an plus tôt.", "mesure": "Le PIB (produit intérieur brut) est la valeur de ce qu'un pays produit en un trimestre ; « réel » veut dire corrigé de l'inflation. Le tableau suit les États-Unis, la zone euro, le Japon, le Royaume-Uni et la Chine.", "calcul": "Chaque trimestre est comparé au même trimestre un an plus tôt (« glissement annuel »). Pour les États-Unis et le Royaume-Uni, l'application le calcule à partir du niveau du PIB ; pour la zone euro, le Japon et la Chine, elle reprend le taux publié par Eurostat (l'office statistique européen) ou par l'OCDE (Organisation de coopération et de développement économiques).", "interpreter": "Pas de seuil officiel : on se repère dans l'historique. Médianes depuis 1990 : États-Unis 2,6 %, Japon 1,1 % ; depuis 1996, zone euro 1,8 % ; depuis 1993, Chine 8 %. Un chiffre négatif veut dire que l'économie produit moins qu'un an plus tôt : 10 trimestres sur 147 aux États-Unis, 31 sur 147 au Japon.", "bouger": "La consommation, les investissements, les dépenses publiques et les exportations. La croissance soutient les bénéfices des entreprises, donc les bourses, et guide les banques centrales.", "liens": ["D13_US", "E5_US", "E3_US", "A1", "G2"], "piege": "L'effet de base : après le creux de 2020 (zone euro −13,8 % au 2e trimestre), le +15,3 % du 2e trimestre 2021 compare simplement à un point très bas. Le dernier chiffre est souvent provisoire ; les trimestres sont datés par leur premier jour."},
"E2": {"titre": "Prévisions de croissance du FMI (Fonds monétaire international)", "phrase": "Le FMI (Fonds monétaire international) publie deux fois par an ses prévisions de croissance du PIB (produit intérieur brut) réel pour chaque pays, pour l'année en cours et les années suivantes.", "mesure": "La croissance attendue de la production de biens et de services d'un pays, en volume (hors hausse des prix), en % par rapport à l'année précédente. Le tableau donne l'année en cours (estimation) et les deux années suivantes (prévisions).", "calcul": "Les économistes du FMI partent des comptes nationaux publiés, puis font des hypothèses sur les prix de l'énergie, les taux d'intérêt, le commerce mondial et la politique budgétaire. Les chiffres paraissent dans les « Perspectives de l'économie mondiale » (World Economic Outlook), en avril et en octobre, avec parfois une mise à jour en janvier et en juillet.", "interpreter": "Comparez surtout les pays entre eux et l'évolution d'une édition à l'autre : une révision à la baisse en octobre, après celle d'avril, signale une dégradation. Pour les grandes économies avancées, une croissance de 1 à 2 % par an est courante ; les pays émergents comme la Chine croissent en général plus vite.", "bouger": "Les prévisions réagissent aux chocs (pétrole, guerre, pandémie, crise financière), aux décisions des banques centrales et aux plans budgétaires. Elles influencent les anticipations de taux et le moral des marchés.", "liens": ["E1_ZE", "E1_US", "E3_BE", "D13_US", "D14"], "piege": "Une prévision n'est pas une donnée : elle est souvent révisée, parfois fortement. La zone euro est un agrégat calculé par le FMI. L'application interroge le FMI une fois par semaine : le tableau change seulement à la parution d'une nouvelle édition."},
"E3": {"titre": "Dette publique en % du PIB — comparaison entre pays (FMI)", "phrase": "Cette série compare ce que les administrations publiques d'un pays doivent encore rembourser à la richesse que ce pays produit en un an.", "mesure": "La dette brute de l'ensemble des administrations publiques (État, collectivités locales, sécurité sociale), rapportée au PIB (produit intérieur brut, la production annuelle). Le FMI (Fonds monétaire international) applique la même définition à tous les pays, d'où la comparaison possible.", "calcul": "Le FMI rassemble les chiffres officiels dans sa base « Perspectives de l'économie mondiale » : une valeur par an et par pays. L'application garde les années observées ; les projections sont présentées à part.", "interpreter": "Le traité européen (protocole n° 12) fixe 60 % du PIB comme référence. Repères tirés des données : la France passe de 37 % en 1990 à plus de 100 % ; l'Italie ne descend jamais sous 100 % ; la Belgique culmine à 139 % en 1993 ; le Japon dépasse 200 % depuis 2013.", "bouger": "Les déficits l'alourdissent ; la croissance et l'inflation l'allègent en proportion du PIB. Les crises la font bondir : zone euro, de 65,8 % en 2007 à 95,9 % en 2020.", "liens": ["E3T_FR", "E4_US", "E5_FR", "B7", "BC_FR_DE"], "piege": "Ne pas la confondre avec la dette trimestrielle d'Eurostat (E3T) ni avec la dette fédérale américaine (sans États fédérés ni communes). Débuts inégaux : 1990 pour la plupart, 1991 pour l'Allemagne, 1995 pour la zone euro et la Chine, 2001 pour les États-Unis. Pour le Japon, la dernière année « observée » peut être plus ancienne que pour les autres."},
"E3T": {"titre": "Dette publique trimestrielle en % du PIB (Eurostat) et dette fédérale américaine", "phrase": "Cette série suit, trimestre après trimestre, la dette des pays de la zone euro rapportée à leur PIB (produit intérieur brut) ; pour les États-Unis, elle ne montre que la dette de l'État fédéral.", "mesure": "Pour la Belgique, l'Allemagne, la France, l'Italie et la zone euro : la dette brute de toutes les administrations publiques, en % du PIB (la production annuelle). Pour les États-Unis : l'État fédéral seulement, sans les États fédérés ni les communes.", "calcul": "Eurostat (l'office statistique de l'Union européenne) publie la dette à la fin de chaque trimestre. Les chiffres américains viennent du Trésor américain, via la base FRED de la Réserve fédérale de Saint-Louis.", "interpreter": "Le repère légal de 60 % (traité européen, protocole n° 12) vise la dette annuelle. Repères tirés des données : l'Allemagne oscille entre 57,6 % (2001) et 81,0 % (2010) ; l'Italie, entre 103,5 % (fin 2007) et 158,2 % (début 2021) ; la dette fédérale américaine passe de 52 % en 1990 à 132,7 % au 2e trimestre 2020.", "bouger": "Les mêmes forces que pour la dette annuelle : déficits, croissance, inflation, taux d'intérêt. Les chocs de 2008-2009 et de 2020 se lisent nettement.", "liens": ["E3_FR", "E4_FR", "E5_FR", "B6", "BC_IT_DE"], "piege": "La courbe américaine n'est pas comparable à celle du FMI (Fonds monétaire international, E3), qui couvre toutes les administrations publiques : ne pas les mélanger. Délai de publication d'environ un trimestre et demi. Débuts : 1990 pour les États-Unis (dans l'application), fin 1995 pour la Belgique, 2000 pour les autres."},
"E4": {"titre": "Dette publique en montant — milliards de monnaie nationale et d'euros", "phrase": "Cette série donne le montant total de la dette publique, en milliards, et non plus en proportion du PIB (produit intérieur brut).", "mesure": "La dette publique brute en milliards de la monnaie du pays, avec un équivalent en euros pour comparer. Pour les États-Unis, c'est la dette de l'État fédéral seulement.", "calcul": "Belgique, Allemagne, France, Italie, zone euro : montants trimestriels d'Eurostat (office statistique européen). États-Unis : dette fédérale trimestrielle (base FRED). Japon, Royaume-Uni, Chine : calcul annuel, dette en % du PIB × PIB nominal, tous deux du FMI (Fonds monétaire international). L'équivalent en euros utilise le dernier cours de change de la période (fin de trimestre ou 31 décembre).", "interpreter": "Un montant brut grimpe presque toujours, car croissance et inflation gonflent aussi les chiffres : mieux vaut le comparer au PIB (E3, E3T). Repères tirés des données : la dette de la zone euro est environ trois fois plus élevée qu'en 2000 ; la dette fédérale américaine, plus de douze fois plus qu'en 1990.", "bouger": "Les déficits l'augmentent, les remboursements la réduisent. En euros, le cours de change joue aussi.", "liens": ["E3_US", "E3T_US", "E5_US", "I1", "IC_EURJPY"], "piege": "En euros, la dette américaine, japonaise, britannique ou chinoise varie avec le change même si le montant en monnaie nationale ne bouge pas. Les séries calculées (Japon, Royaume-Uni, Chine) sont annuelles et approximatives, car révisables. La dette américaine est fédérale seulement."},
"E5": {"titre": "Solde budgétaire en % du PIB (FMI)", "phrase": "Cette série indique si les administrations publiques d'un pays dépensent plus qu'elles ne reçoivent, en proportion de la richesse produite.", "mesure": "Les recettes moins les dépenses de l'ensemble des administrations publiques, rapportées au PIB (produit intérieur brut, la production annuelle). Un chiffre négatif est un déficit : le pays emprunte pour combler l'écart. Un chiffre positif est un excédent.", "calcul": "Le FMI (Fonds monétaire international) rassemble les chiffres officiels dans sa base « Perspectives de l'économie mondiale » : une valeur par an et par pays. L'application garde les années considérées comme observées ; les projections sont présentées à part.", "interpreter": "Le traité européen (protocole n° 12) retient 3 % du PIB comme déficit de référence. Repères tirés des données : la zone euro oscille entre −7,3 % (1995) et −0,4 % (2018) ; la France n'a connu aucun excédent depuis 1990 ; l'Allemagne a atteint +1,9 % en 2018 ; les États-Unis, −14,1 % en 2020.", "bouger": "En récession, les recettes baissent et les dépenses montent : le déficit se creuse, comme en 2009 et en 2020. Plans de relance, baisses d'impôts et vieillissement jouent aussi. Les déficits alimentent la dette (E3).", "liens": ["E3_FR", "E3T_FR", "E1_ZE", "B1", "B7"], "piege": "Un déficit n'est pas la dette : c'est un flux annuel, alors que la dette est le total accumulé. Séries annuelles aux débuts inégaux : 1990 pour la plupart, 1991 pour l'Allemagne et la zone euro, 2001 pour les États-Unis. Les années les plus récentes sont des estimations, révisables."},
"ETF_H": {"titre": "ETF matières premières diversifiées — DBC", "phrase": "DBC est un ETF (Exchange-Traded Fund, fonds coté en bourse) qui permet de suivre un panier de matières premières.", "mesure": "La valeur d'une part du fonds, en dollars. Le panier mêle énergie, métaux et produits agricoles : c'est un baromètre des prix des matières premières dans leur ensemble.", "calcul": "Le fonds (Invesco DB Commodity Index Tracking Fund) achète des contrats à terme sur ces matières et les renouvelle régulièrement. Le tableau de bord reprend le cours de clôture Yahoo, hors dividendes : d'éventuelles distributions ne sont pas ajoutées.", "interpreter": "Pas de seuil. Repères vérifiés (valeurs de fin de mois) : environ 44,8 dollars fin juin 2008 (comme le Brent, au plus haut), environ 21,2 dollars fin décembre 2008 (−53 %), puis environ 10,9 dollars fin avril 2020, soit environ 76 % sous le sommet de 2008.", "bouger": "La croissance mondiale, l'inflation, le dollar et surtout le pétrole. Le fonds suit en effet les contrats à terme, dont le renouvellement peut coûter ou rapporter de l'argent.", "liens": ["H1", "H3", "H6", "I6", "C1"], "piege": "Un ETF n'est pas la matière première elle-même : il peut s'écarter des prix au comptant à cause du renouvellement des contrats. Le cours est en dollars et hors dividendes, donc inférieur au rendement réel. Historique depuis février 2006."},
"F1": {"titre": "Bilan de la Fed — l'actif de la banque centrale américaine", "phrase": "Cette série mesure la taille du bilan de la Fed (Réserve fédérale), c'est-à-dire tout ce que la banque centrale américaine détient, surtout des obligations.", "mesure": "La Fed achète des titres, surtout des bons du Trésor américain et des obligations adossées à des prêts hypothécaires. Le total de ces actifs, en milliards de dollars, est son bilan.", "calcul": "La Fed publie son bilan chaque semaine ; l'application le reprend via la base FRED de la Réserve fédérale de Saint-Louis. Le graphique d'historique est mensuel.", "interpreter": "Pas de seuil : c'est la tendance qui compte. Un bilan qui gonfle correspond à un QE (quantitative easing, assouplissement quantitatif) : la banque achète des titres, injecte de la monnaie et tire les taux longs vers le bas. Un bilan qui se réduit, à un QT (quantitative tightening, resserrement quantitatif). Dans les données : environ 730 milliards de dollars fin 2002, sommet d'environ 8 900 milliards au printemps 2022, puis recul.", "bouger": "Les décisions de la Fed face aux crises : bond après 2008, puis de nouveau en 2020. Il influence les taux longs (B1) et, indirectement, les bourses (G2).", "liens": ["F5_FED", "F6", "A1", "B1", "t:qeqt"], "piege": "Le montant est en dollars courants : pour comparer avec d'autres banques ou d'autres époques, on le rapporte au PIB (produit intérieur brut, F5). La série n'existe que depuis décembre 2002. Un bilan qui se réduit n'est pas une hausse des taux : ce sont deux outils distincts."},
"F2": {"titre": "Bilan de la BCE — l'actif de l'Eurosystème", "phrase": "Cette série mesure la taille du bilan de la BCE (Banque centrale européenne), c'est-à-dire tout ce que détient l'Eurosystème.", "mesure": "La BCE et les banques centrales nationales de la zone euro forment l'Eurosystème. Son bilan regroupe les titres qu'il a achetés et ses prêts aux banques, en milliards d'euros.", "calcul": "La BCE publie ce bilan chaque semaine ; l'application le reprend tel quel, en milliards d'euros. Le graphique d'historique est mensuel.", "interpreter": "Pas de seuil : on regarde la tendance. Un bilan qui gonfle correspond à un QE (quantitative easing, assouplissement quantitatif), un bilan qui se réduit à un QT (quantitative tightening, resserrement quantitatif). Dans les données : environ 700 milliards d'euros en 1999, sommet d'environ 8 800 milliards en 2022, puis recul.", "bouger": "Les décisions de la BCE face aux crises : crise de la dette de la zone euro, puis pandémie de 2020. Il influence les taux longs de la zone euro (B5) et la liquidité des banques.", "liens": ["F5_BCE", "F7", "A2", "B5_10A", "t:qeqt"], "piege": "Le périmètre change quand de nouveaux pays entrent dans la zone euro : un petit saut peut venir d'un élargissement, pas d'une décision. Le montant est en euros courants : pour comparer, on le rapporte au PIB (produit intérieur brut, F5). La série part de janvier 1999."},
"F3": {"titre": "Bilan de la Banque du Japon — son actif total", "phrase": "Cette série mesure la taille du bilan de la Banque du Japon, c'est-à-dire tout ce qu'elle détient, surtout des obligations de l'État japonais.", "mesure": "La Banque du Japon (BoJ, pour Bank of Japan) achète des titres pour soutenir l'économie. Le total de son actif, ici en milliards de yens, est la taille de son bilan.", "calcul": "Chiffre de fin de mois publié par la Banque du Japon, repris via la base FRED de la Réserve fédérale de Saint-Louis. La source compte en unités de 100 millions de yens : l'application convertit en milliards de yens, d'où des montants en centaines de milliers.", "interpreter": "Pas de seuil : on regarde la tendance. Hausse = QE (quantitative easing, assouplissement quantitatif) ; baisse = QT (quantitative tightening, resserrement quantitatif). Dans les données : environ 80 000 milliards de yens en 1998, sommet d'environ 765 000 en 2024. Rapporté au PIB (produit intérieur brut, F5), ce bilan dépasse largement ceux des autres grandes banques centrales, jusqu'à 129 %.", "bouger": "Les choix de la banque pour soutenir la croissance, relancer l'inflation et contenir les taux longs japonais (B10). Une dette publique très élevée (E3) en est l'arrière-plan.", "liens": ["F5_BOJ", "A5", "B10", "E3_JP", "t:qeqt"], "piege": "Comparer des yens à des dollars n'a pas de sens : on passe par le % du PIB (F5). La valeur de chaque mois est celle de la fin du mois, même si la date affichée est le 1er."},
"F4": {"titre": "Bilan de la Banque d'Angleterre — son actif total (source BRI)", "phrase": "Cette série mesure la taille du bilan de la banque centrale du Royaume-Uni, avec environ quatre mois de retard.", "mesure": "La Banque d'Angleterre (BoE, pour Bank of England) détient surtout des obligations de l'État britannique. Le total de son actif, en milliards de livres, est la taille de son bilan.", "calcul": "Les chiffres viennent de la BRI (Banque des règlements internationaux, la banque des banques centrales), qui les assemble à partir de plusieurs publications de la Banque d'Angleterre : une valeur par mois, en milliards de livres.", "interpreter": "Pas de seuil : on regarde la tendance. Hausse = QE (quantitative easing, assouplissement quantitatif) ; baisse = QT (quantitative tightening, resserrement quantitatif). Dans les données : 18 milliards de livres en 1990, puis de l'ordre de 100 milliards (entre 36 et 105) de mai 1999 à août 2008. Le bilan bondit ensuite à plus de 250 milliards en octobre 2008, atteint un sommet d'environ 1 120 milliards fin 2021, avant de reculer.", "bouger": "Les décisions de la Banque d'Angleterre pendant la crise de 2008 et en 2020. Il influence les taux des emprunts d'État britanniques (B9) et, indirectement, la livre (I4).", "liens": ["F5_BOE", "A4", "B9", "I4", "t:qeqt"], "piege": "Le dernier point date d'environ quatre mois : il ne dit rien des mois récents. L'application remonte à 1990, la BRI bien plus loin. Pour comparer avec d'autres pays, on passe par le % du PIB (produit intérieur brut, F5)."},
"F5": {"titre": "Bilans des banques centrales en % du PIB (Fed, BCE, Banque du Japon, Banque d'Angleterre)", "phrase": "Cette série compare la taille du bilan de chaque banque centrale à la richesse produite par son économie en un an.", "mesure": "Le bilan d'une banque centrale divisé par le PIB (produit intérieur brut) de sa zone, ce qui rend comparables la Fed (Réserve fédérale, États-Unis), la BCE (Banque centrale européenne), la Banque du Japon et la Banque d'Angleterre malgré leurs monnaies.", "calcul": "Pour chaque trimestre : bilan de fin de trimestre ÷ PIB nominal (en prix courants) des quatre derniers trimestres. Le PIB est annualisé aux États-Unis et au Japon (moyenne des quatre trimestres), trimestriel ailleurs (somme).", "interpreter": "Pas de seuil : on compare à l'historique. Sommets : fin 2021 pour la Fed (36,9 %), la BCE (67,4 %) et la Banque d'Angleterre (48,0 %), début 2021 pour la Banque du Japon (128,9 %). Creux : 6,1 % pour la Fed, 10,2 % pour la BCE, 12,8 % pour la Banque du Japon, 2,1 % pour la Banque d'Angleterre.", "bouger": "Le QE (quantitative easing, assouplissement quantitatif) fait monter le ratio, le QT (quantitative tightening, resserrement quantitatif) le fait baisser, tout comme une forte croissance du PIB.", "liens": ["F1", "F2", "F3", "F4", "t:qeqt"], "piege": "Le ratio attend la publication du PIB : son dernier point peut être plus ancien que ceux des bilans (F1 à F4). Les périmètres des bilans diffèrent un peu : lisez les écarts entre pays comme des ordres de grandeur. Débuts : 1998 (Banque du Japon), 1999 (BCE), fin 2002 (Fed), fin 1990 (Banque d'Angleterre)."},
"F6": {"titre": "M2 américaine — la masse monétaire (niveau et croissance annuelle)", "phrase": "M2 mesure la quantité d'argent disponible dans l'économie américaine ; sa croissance annuelle dit à quelle vitesse elle augmente.", "mesure": "M2 additionne les billets, les dépôts à vue, les comptes d'épargne, les petits dépôts à terme et les fonds monétaires des particuliers : l'argent que l'on peut dépenser ou mobiliser vite. Le montant est en milliards de dollars.", "calcul": "La Fed (Réserve fédérale des États-Unis) publie M2 chaque mois, corrigée des variations saisonnières ; l'application la reprend via la base FRED. La croissance annuelle compare le mois au même mois un an plus tôt.", "interpreter": "Pas de seuil officiel. Depuis 1990, la croissance annuelle médiane est d'environ 5,6 % ; 10 % des mois sont sous 1,4 %, 10 % au-dessus de 9,3 %. Extrêmes : +26,8 % en février 2021, puis un recul de décembre 2022 à février 2024 (minimum −4,7 % en avril 2023), seule contraction de la série depuis 1990.", "bouger": "Les prêts des banques, les décisions de la Fed (voir F1) et les dépenses publiques : l'envolée de 2020-2021 suit les plans de soutien. Certains économistes y voient un signal avancé de l'inflation (C1), d'autres le contestent.", "liens": ["F7", "F1", "C1", "A1", "t:glissement"], "piege": "Le niveau de M2 monte presque toujours : seule la croissance annuelle est parlante. La publication a environ un mois de retard et les derniers chiffres sont révisables. M2 américaine et M3 de la zone euro (F7) ne sont pas des mesures identiques."},
"F7": {"titre": "M3 de la zone euro — croissance annuelle de la masse monétaire", "phrase": "Cette série indique de combien la quantité d'argent en circulation dans la zone euro a augmenté en un an.", "mesure": "M3 est la définition large de la monnaie selon la BCE (Banque centrale européenne) : billets, dépôts à vue et d'épargne, dépôts à terme de moins de deux ans et placements très liquides comme les parts de fonds monétaires. Elle suit la création de monnaie et de crédit.", "calcul": "La BCE publie chaque mois ce taux de croissance : M3 du mois comparée à celle du même mois un an plus tôt (« glissement annuel »). L'application reprend le taux publié.", "interpreter": "Pas de seuil : on compare à l'historique depuis 1990. Croissance médiane d'environ 5,1 % ; 10 % des mois sont sous 1,6 %, 10 % au-dessus de 8,8 %. Pic de 12,6 % fin 2007 ; croissance négative en 2009-2010 (brièvement) et en 2023, avec un minimum de −1,3 % en août 2023.", "bouger": "Les prêts des banques aux ménages et aux entreprises, la politique de la BCE (voir F2) et l'attrait de l'épargne. Un crédit qui se tarit fait ralentir M3 ; certains économistes y voient un signal avancé de l'activité et de l'inflation (C5).", "liens": ["F6", "F2", "C5", "A2", "t:glissement"], "piege": "Le périmètre de la zone euro change quand de nouveaux pays entrent : la série n'est pas parfaitement homogène sur 35 ans. Le dernier point est provisoire et révisable. M3 euro et M2 américaine (F6) ne sont pas équivalentes."},
"G1": {"titre": "BEL 20 — le thermomètre de la Bourse de Bruxelles", "phrase": "Le BEL 20 suit le cours des 20 principales entreprises cotées à Bruxelles : c'est le repère habituel de la Bourse belge.", "mesure": "L'évolution d'ensemble du prix des actions des grandes sociétés cotées sur Euronext Bruxelles (la Bourse de Bruxelles). Plusieurs de ces groupes vendent surtout à l'étranger : l'indice reflète donc autant l'économie mondiale que l'économie belge.", "calcul": "Chaque société pèse selon la valeur en bourse des actions réellement disponibles au public (capitalisation flottante), avec un plafond pour qu'une seule ne domine pas. Il s'exprime en points. Ici, c'est la clôture quotidienne, dividendes non ajoutés (« hors dividendes »).", "interpreter": "Il n'existe pas de « bon » niveau. Regardez la variation sur 12 mois et sa position dans l'historique (percentile : au 90e percentile, 10 % des périodes passées ont fait mieux). Repères tirés des clôtures mensuelles : de mai 2007 à février 2009, l'indice a perdu environ 64 % ; il n'a retrouvé son niveau de mai 2007 qu'en août 2025.", "bouger": "Les résultats des grandes entreprises, les taux de la BCE (Banque centrale européenne), l'humeur des bourses mondiales (Wall Street donne souvent le ton) et les crises financières.", "liens": ["G2", "G5", "G7", "A2", "J2"], "piege": "Peu de valeurs : quelques sociétés suffisent à le faire bouger. Il est hors dividendes, donc il sous-estime ce que gagne un investisseur qui les encaisse. Historique depuis avril 1991 seulement (rien avant)."},
"G10": {"titre": "Shanghai Composite — la Bourse de Shanghai", "phrase": "Le Shanghai Composite suit l'ensemble des actions cotées à la Bourse de Shanghai, l'une des deux grandes places de Chine continentale.", "mesure": "L'évolution d'ensemble de la valeur des sociétés chinoises cotées à Shanghai : banques, énergie, industrie, souvent contrôlées par l'État. L'accès des investisseurs étrangers y est limité et les petits porteurs locaux y jouent un grand rôle.", "calcul": "Chaque société pèse selon sa valeur en bourse. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : sommet en octobre 2007, puis chute d'environ 71 % en un an (octobre 2008). Depuis, aucune clôture mensuelle de la base n'a dépassé ce sommet.", "bouger": "La politique du gouvernement chinois et de la banque centrale, la croissance de l'économie chinoise, l'immobilier, les tensions avec les États-Unis et l'humeur des petits investisseurs.", "liens": ["G11", "G12", "A6", "I3", "G9"], "piege": "Historique depuis juillet 1997 seulement (pas 1990). Les fêtes chinoises (Nouvel An lunaire, fête nationale en octobre, etc.) entraînent des fermetures de 11 à 20 jours : ces trous sont réels et ne sont jamais comblés. Hors dividendes."},
"G11": {"titre": "ETF qui suit le CSI 300 — la Chine continentale en fonds coté", "phrase": "Cette série est le cours d'un ETF (Exchange Traded Fund, fonds indiciel coté en bourse) qui copie le CSI 300 (China Securities Index), l'indice des 300 grandes entreprises de Shanghai et de Shenzhen. Ce n'est pas l'indice lui-même.", "mesure": "L'évolution de la valeur des grandes sociétés cotées en Chine continentale (Shanghai et Shenzhen), tous secteurs confondus.", "calcul": "Le fonds achète les actions de l'indice et suit sa performance. Son prix est exprimé en yuans, non en points d'indice : une part vaut quelques yuans (entre 2 et 5 environ depuis 2012). On utilise ce fonds parce que l'indice n'est pas disponible gratuitement de façon fiable. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : de mai 2015 à février 2016, le fonds a perdu environ 41 % ; son plus haut mensuel date de janvier 2021.", "bouger": "La croissance chinoise, la politique du gouvernement et de la banque centrale, l'immobilier, le yuan et l'humeur des investisseurs.", "liens": ["G10", "G12", "I3", "A6", "t:etf"], "piege": "Ce n'est pas l'indice : de petits écarts avec le CSI 300 existent. Historique court : depuis mai 2012 seulement. Le cours est en yuans : pour un Belge, le taux de change yuan-euro joue aussi. Hors dividendes."},
"G12": {"titre": "Hang Seng — la Bourse de Hong Kong", "phrase": "Le Hang Seng suit le cours des principales entreprises cotées à Hong Kong ; c'est le repère de la finance asiatique et de la Chine ouverte au monde.", "mesure": "L'évolution d'ensemble de la valeur de grands groupes cotés à Hong Kong : banques, assurance, immobilier, et surtout de grandes sociétés chinoises (technologie, internet). Il reflète donc largement la confiance envers l'économie chinoise.", "calcul": "Chaque société pèse selon la valeur en bourse des actions disponibles au public. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes. Le dollar de Hong Kong est arrimé au dollar américain.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : d'octobre 2007 à février 2009, il a perdu environ 59 % ; sa clôture mensuelle la plus haute de la base date de janvier 2018 et n'a pas été dépassée depuis.", "bouger": "La politique de Pékin, l'économie chinoise, les taux de la Fed (Réserve fédérale, la banque centrale américaine) — Hong Kong suit en pratique les taux américains grâce à son arrimage — et les tensions géopolitiques.", "liens": ["G10", "G11", "A1", "I3", "J1"], "piege": "Le Hang Seng n'est pas le miroir de l'économie de Hong Kong, mais surtout celui de grands groupes chinois et de banques. Hors dividendes : il sous-estime donc le rendement, les banques en versant beaucoup."},
"G13": {"titre": "MSCI World (via l'ETF iShares) — les grandes bourses du monde développé", "phrase": "Cette série est le cours d'un ETF (Exchange Traded Fund, fonds indiciel coté en bourse) qui copie le MSCI World (Morgan Stanley Capital International), l'indice des grandes et moyennes entreprises des pays développés ; le cours est en euros.", "mesure": "L'évolution d'ensemble des actions des pays riches (États-Unis, Europe, Japon, etc.). Les États-Unis y pèsent de loin le plus lourd.", "calcul": "L'ETF iShares Core MSCI World, coté à Amsterdam, achète les actions de l'indice et suit sa performance. Son cours est en euros, pas en points d'indice. La clôture est non ajustée, mais cet ETF est de capitalisation : les dividendes sont réinvestis dans le fonds et se retrouvent donc dans son cours.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repère tiré des clôtures mensuelles : de janvier à mars 2020 (pandémie), le fonds a perdu environ 19 %.", "bouger": "Surtout Wall Street, puis l'Europe et le Japon ; et le taux de change euro-dollar : si l'euro monte face au dollar, la valeur en euros des actions américaines baisse.", "liens": ["G2", "I1", "J1", "t:etf", "t:dividendes"], "piege": "Historique court : depuis septembre 2009, donc la crise de 2008 n'apparaît pas. Ce n'est pas l'indice lui-même. Si la source tombait en panne, un autre fonds, coté en dollars, remplacerait la série entière sans jamais lui être raccordé."},
"G2": {"titre": "S&P 500 — les 500 grandes entreprises américaines", "phrase": "Le S&P 500 suit le cours de 500 grandes entreprises cotées aux États-Unis ; c'est le principal repère de la bourse américaine, et même mondiale.", "mesure": "L'évolution d'ensemble de la valeur en bourse des grands groupes américains, de la technologie à la santé, la banque ou l'énergie. Comme ces sociétés vendent dans le monde entier, il reflète aussi la santé de l'économie mondiale.", "calcul": "Standard & Poor's (S&P) le calcule en pondérant chaque entreprise selon sa taille boursière : les plus grosses pèsent beaucoup plus que les petites. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes (non ajustée des dividendes versés).", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : d'octobre 2007 à février 2009, il a perdu un peu plus de la moitié de sa valeur (environ 53 %) et n'a retrouvé son niveau qu'en mars 2013.", "bouger": "Les bénéfices des entreprises, les taux de la Fed (Réserve fédérale, la banque centrale américaine), l'inflation et la peur des investisseurs, que mesure le VIX (indice de la peur). Il influence presque toutes les autres bourses.", "liens": ["J1", "G4", "G3", "A1", "B1"], "piege": "Hors dividendes : il ne mesure pas le rendement complet d'un investisseur. Les très grandes sociétés pèsent lourd : il peut monter alors que la plupart des actions stagnent. Il est en dollars : le change compte pour un Belge."},
"G3": {"titre": "Dow Jones Industrial Average — 30 géants américains", "phrase": "Le Dow Jones suit le cours de 30 très grandes entreprises américaines ; c'est l'un des plus anciens et des plus cités des indices de Wall Street.", "mesure": "L'évolution du prix des actions de 30 sociétés américaines de premier plan, choisies par un comité. C'est un échantillon très étroit, comparé aux 500 sociétés du S&P 500 (indice américain élargi).", "calcul": "Particularité : il est pondéré par le prix des actions, pas par la taille des entreprises. Une société dont l'action vaut 400 $ pèse quatre fois plus qu'une autre dont l'action vaut 100 $, même si elle est plus petite. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : d'octobre 2007 à février 2009, il a perdu environ 49 % ; il n'a retrouvé son niveau qu'en février 2013.", "bouger": "Les bénéfices des entreprises, les taux de la Fed (Réserve fédérale, la banque centrale américaine), l'inflation et le climat économique mondial. Il suit en général la même direction que le S&P 500, avec des écarts.", "liens": ["G2", "G4", "J1", "A1", "B1"], "piege": "Son mode de calcul est ancien : le poids d'une société dépend du prix de son action, ce qui est un peu arbitraire. Hors dividendes. Historique depuis janvier 1992 seulement (pas 1990)."},
"G4": {"titre": "Nasdaq Composite — la bourse américaine de la technologie", "phrase": "Le Nasdaq Composite suit l'ensemble des actions cotées sur le Nasdaq, la bourse électronique américaine, très orientée vers la technologie.", "mesure": "L'évolution d'ensemble de plusieurs milliers d'actions, dont de nombreux groupes du numérique, des logiciels, des puces électroniques et de la biotechnologie. Il est plus sensible aux paris sur la croissance future que le S&P 500 (500 grandes sociétés américaines, tous secteurs).", "calcul": "Le Nasdaq (National Association of Securities Dealers Automated Quotations) le calcule en pondérant chaque société selon sa valeur en bourse : les plus grosses dominent. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repère tiré des clôtures mensuelles : de février 2000 à septembre 2002 (éclatement de la bulle internet), il a perdu environ 75 % ; il n'a retrouvé son niveau de février 2000 qu'en novembre 2014.", "bouger": "Les anticipations de bénéfices des entreprises technologiques et surtout les taux d'intérêt : quand ils montent, les actions « de croissance » perdent plus que les autres. Il bouge généralement davantage que le S&P 500, à la hausse comme à la baisse.", "liens": ["G2", "J1", "B1", "A1", "t:dividendes"], "piege": "Ne le confondez pas avec le Nasdaq-100 (les 100 plus grosses sociétés du Nasdaq), qui est un autre indice. Le Composite est très concentré sur quelques géants. Hors dividendes."},
"G5": {"titre": "Euro Stoxx 50 — les 50 grands groupes de la zone euro", "phrase": "L'Euro Stoxx 50 suit le cours de 50 grandes entreprises des pays qui partagent l'euro ; c'est le repère de la bourse de la zone euro.", "mesure": "L'évolution d'ensemble de la valeur en bourse de grands groupes de la zone euro (industrie, luxe, énergie, banque, technologie), choisis dans plusieurs pays. Il ne contient ni société britannique ni société suisse.", "calcul": "Stoxx, société spécialisée dans les indices, pondère chaque entreprise selon sa valeur en bourse (avec un plafond par société). Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : de mai 2007 à février 2009, il a perdu environ 56 % ; il n'a retrouvé son niveau de mai 2007 qu'en décembre 2023, soit plus de seize ans plus tard.", "bouger": "Les bénéfices des grands groupes, les décisions de la BCE (Banque centrale européenne), les crises de la dette ou de l'énergie en Europe, et l'humeur de Wall Street.", "liens": ["G1", "G6", "G7", "A2", "J2"], "piege": "Historique court : la série ne commence qu'en mars 2007, sans les décennies précédentes ; les comparaisons avec le passé portent donc sur moins de vingt ans. Hors dividendes."},
"G6": {"titre": "DAX — les 40 grandes entreprises allemandes", "phrase": "Le DAX suit les 40 plus grandes entreprises cotées à Francfort, avec une particularité : les dividendes y sont réinvestis.", "mesure": "L'évolution d'ensemble de la valeur des grands groupes allemands (automobile, industrie, chimie, assurance, logiciels). Beaucoup exportent : il dépend donc de la conjoncture mondiale.", "calcul": "DAX signifie Deutscher Aktienindex (indice allemand des actions). Chaque société pèse selon sa valeur en bourse. Particularité : c'est un indice de performance. Les dividendes versés sont supposés réinvestis dans l'indice, qui monte donc un peu plus que les cours seuls.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : de février 2000 à mars 2003, il a perdu environ 68 % ; il a retrouvé son niveau de 2000 dès mai 2007, alors que le CAC 40 (indice français) n'est revenu au sien qu'en 2021, en partie parce que le DAX compte les dividendes.", "bouger": "Les exportations allemandes, le prix de l'énergie, la croissance en Chine et aux États-Unis, les taux de la BCE (Banque centrale européenne) et la politique économique de Berlin.", "liens": ["G7", "G5", "C8", "B4", "t:dividendes"], "piege": "Ne le comparez pas tel quel aux autres indices boursiers du tableau de bord (S&P 500, CAC 40, etc.), qui sont des indices de prix, sans dividendes : le DAX a un avantage mécanique, qui s'accumule année après année."},
"G7": {"titre": "CAC 40 — les 40 grandes entreprises françaises", "phrase": "Le CAC 40 suit le cours de 40 grandes sociétés cotées à Paris ; c'est le repère habituel de la Bourse française.", "mesure": "L'évolution d'ensemble de la valeur des grands groupes français : luxe, énergie, banque, aéronautique, grande consommation. Ils réalisent la majeure partie de leur activité hors de France : il reflète donc l'économie mondiale autant que l'économie française.", "calcul": "CAC signifie Cotation assistée en continu. Chaque société pèse selon la valeur en bourse des actions disponibles au public. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes. Il existe une version avec dividendes réinvestis, non utilisée ici.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : d'août 2000 à mars 2003, il a perdu environ 60 % ; il n'a retrouvé son niveau d'août 2000 qu'en août 2021, plus de vingt ans plus tard.", "bouger": "Les ventes de luxe et d'énergie, les banques, les taux de la BCE (Banque centrale européenne), la politique française et l'humeur de Wall Street.", "liens": ["G6", "G5", "G1", "A2", "J2"], "piege": "Hors dividendes : à long terme, l'écart avec un indice qui les réinvestit (comme le DAX, l'indice allemand) devient considérable. Historique depuis mars 1990 (il manque janvier et février 1990)."},
"G8": {"titre": "FTSE 100 — les 100 grandes entreprises de Londres", "phrase": "Le FTSE 100, surnommé « Footsie », suit le cours des 100 plus grosses sociétés cotées à la Bourse de Londres.", "mesure": "L'évolution d'ensemble de la valeur des grands groupes britanniques : pétrole et gaz, mines, banques, pharmacie, grande consommation. Une grande partie de leurs ventes se fait à l'étranger, en dollars ou en euros.", "calcul": "FTSE vient de Financial Times Stock Exchange. Chaque société pèse selon la valeur en bourse des actions disponibles au public. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : de décembre 1999 à janvier 2003, il a perdu environ 48 % ; il n'a retrouvé son niveau de fin 1999 qu'en février 2015.", "bouger": "Le prix du pétrole et des métaux, les banques, les décisions de la Banque d'Angleterre et la livre sterling : quand la livre baisse, les ventes réalisées à l'étranger valent plus de livres, ce qui soutient souvent l'indice.", "liens": ["A4", "I4", "H1", "G7", "J2"], "piege": "Hors dividendes : les grandes sociétés britanniques en versent beaucoup, donc l'écart avec le rendement réel est notable. L'indice dit peu de l'économie du Royaume-Uni elle-même, tant il est dominé par des groupes mondiaux."},
"G9": {"titre": "Nikkei 225 — les 225 grandes entreprises japonaises", "phrase": "Le Nikkei 225 suit le cours de 225 grandes sociétés cotées à la Bourse de Tokyo ; c'est le repère habituel du Japon.", "mesure": "L'évolution du prix des actions de grands groupes japonais (automobile, électronique, machines, commerce). Beaucoup exportent : l'indice dépend de la demande mondiale et du yen.", "calcul": "Il porte le nom du journal économique japonais qui l'a créé (Nikkei). Comme le Dow Jones, il est pondéré par le prix des actions, pas par la taille des sociétés. Il s'exprime en points. Ici, c'est la clôture quotidienne, hors dividendes.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles : de janvier 1990 (juste après la bulle japonaise) à février 2009, il a perdu environ 80 % ; il n'est repassé au-dessus de son niveau de janvier 1990 qu'en février 2024.", "bouger": "Le yen (quand il baisse, les exportateurs gagnent plus de yens), la politique de la Banque du Japon, la demande mondiale et Wall Street.", "liens": ["I2", "A5", "B10", "G2", "G10"], "piege": "L'historique de la base commence en janvier 1990, près du sommet de la bulle : ne le lisez pas comme une évolution « normale ». En mai 2019, la bourse est restée fermée une dizaine de jours (jours fériés exceptionnels liés à l'avènement du nouvel empereur) : ce trou est réel."},
"H1": {"titre": "Pétrole Brent — la référence européenne du prix du pétrole", "phrase": "Le Brent est le prix d'un baril de pétrole extrait en mer du Nord, l'une des deux grandes références mondiales du prix du pétrole.", "mesure": "Le prix en dollars d'un baril (159 litres) de pétrole brut livrable tout de suite, dit « au comptant ». Il reflète l'équilibre entre offre et demande mondiales.", "calcul": "L'EIA (Agence américaine d'information sur l'énergie) relève ce prix chaque jour ; le tableau de bord le reprend via FRED (base de données de la Banque fédérale de réserve de Saint-Louis), avec quelques jours de retard. Les derniers jours viennent du contrat à terme Yahoo (BZ=F), un achat à prix fixé aujourd'hui pour livraison future : marqués « provisoires », ils ne sont ajoutés que si l'écart reste sous 2 %.", "interpreter": "Pas de seuil officiel. Sur les valeurs de fin de mois depuis 1990, le Brent est resté sous 17 dollars un mois sur dix et au-dessus de 108 un mois sur dix ; médiane : environ 51. Repères : environ 138 dollars fin juin 2008, puis environ 36 fin décembre 2008.", "bouger": "Il monte quand l'économie tourne à plein ou que l'offre se raréfie (OPEP+ : pays exportateurs de pétrole et partenaires ; guerres ; tensions) et baisse en récession. Il pèse sur l'inflation (carburants, chauffage).", "liens": ["H2", "H8_BNO", "C1", "I6", "J3"], "piege": "Prix au comptant et contrat à terme diffèrent parfois de plusieurs %. Les jours fériés américains laissent des trous dans la série FRED, qui restent des trous. Prix en dollars : l'euro compte aussi pour un Européen."},
"H10": {"titre": "ETF immobilier coté américain — VNQ (Vanguard Real Estate)", "phrase": "VNQ est un ETF (fonds coté en bourse) qui regroupe des sociétés immobilières cotées aux États-Unis.", "mesure": "La valeur d'une part, en dollars. Le fonds détient surtout des REIT (Real Estate Investment Trusts, sociétés qui possèdent et louent des immeubles : bureaux, entrepôts, centres commerciaux, logements). C'est une exposition à l'immobilier par la bourse, sans acheter de bien.", "calcul": "Cours de clôture Yahoo, hors dividendes. Or les REIT distribuent l'essentiel de leurs bénéfices : le rendement réel est donc nettement supérieur à ce que montre la courbe.", "interpreter": "Pas de seuil. Repères vérifiés (valeurs de fin de mois) : de fin décembre 2007 (environ 61 dollars) à fin février 2009 (environ 24 dollars), −61 % pendant la crise des crédits immobiliers ; de fin décembre 2021 (environ 116 dollars) à fin décembre 2022 (environ 82 dollars), −29 % quand les taux d'intérêt ont fortement monté.", "bouger": "Les taux d'intérêt (des taux élevés renchérissent les emprunts et concurrencent les loyers), la santé de l'économie, les loyers et l'occupation des immeubles.", "liens": ["H11", "B1", "G2", "A1"], "piege": "Ce n'est pas le prix des maisons : il se comporte plutôt comme une action. Cours en dollars et hors dividendes. Il représente l'immobilier américain, pas belge."},
"H11": {"titre": "ETF immobilier coté européen — iShares European Property Yield (IPRP)", "phrase": "IPRP est un ETF (fonds coté en bourse) qui regroupe des sociétés immobilières cotées en Europe, choisies pour leurs dividendes.", "mesure": "La valeur d'une part, en euros, cotée à Amsterdam. L'indice suivi couvre l'immobilier coté européen hors Royaume-Uni, à dividendes élevés. Le fonds permet d'investir dans l'immobilier européen par la bourse, sans acheter de bien.", "calcul": "Cours de clôture Yahoo de la cotation d'Amsterdam (IPRP.AS), en euros, hors dividendes. Le fonds les distribue : le cours baisse du montant versé, et la courbe sous-estime donc le rendement. Le même fonds est aussi coté à Londres (en pence) et à Milan, mais ces cotations ne sont pas utilisées.", "interpreter": "Pas de seuil. Repères vérifiés (valeurs de fin de mois) : environ 15,2 euros fin mars 2009 ; environ 47,2 euros fin janvier 2020, puis environ 34,4 euros fin mars 2020 (−27 % en deux mois, début de la pandémie) ; de fin décembre 2021 (environ 43,3 euros) à fin décembre 2022 (environ 25,9 euros), −40 % quand les taux ont monté.", "bouger": "Les taux d'intérêt, notamment ceux de la BCE (Banque centrale européenne), le coût des emprunts, les loyers, l'occupation des bureaux et des commerces.", "liens": ["H10", "A2", "B4", "G5"], "piege": "Historique depuis janvier 2008 seulement. Le panier est restreint : l'ETF peut très bien s'éloigner de l'immobilier belge. Cours hors dividendes, comparable à un indice de prix mais pas à un rendement."},
"H12": {"titre": "ETF obligations d'État américaines à plus de 20 ans — TLT", "phrase": "TLT est un ETF (fonds coté en bourse) qui détient des obligations de l'État américain à très long terme : son prix baisse quand les taux longs montent.", "mesure": "La valeur d'une part, en dollars. Une obligation est un prêt à l'État, qui verse un intérêt (le coupon) ; ici, il reste plus de 20 ans avant le remboursement.", "calcul": "Le fonds (iShares) détient des bons du Trésor américain de plus de 20 ans. Le cours est celui de clôture de Yahoo, hors dividendes : les intérêts versés n'étant pas ajoutés, la courbe sous-estime le rendement total de l'ETF.", "interpreter": "Quand le taux des emprunts d'État à 10 ans monte, le cours baisse, d'autant plus que la durée est longue. Repères vérifiés : de fin juillet 2020 (environ 171 dollars) à fin décembre 2022 (environ 100 dollars), −42 %, alors que les taux montaient. Sur la même période, IEF (7-10 ans) a perdu environ 22 %.", "bouger": "L'inflation attendue, les décisions de la Fed (Réserve fédérale, banque centrale américaine), les déficits publics, et la fuite vers la sécurité en cas de panique, qui fait monter le prix.", "liens": ["B1", "H13", "A1", "D1", "G2"], "piege": "Croire qu'une obligation d'État est sans risque : le risque de défaut est faible, mais le prix peut chuter. Cours en dollars et hors coupons."},
"H13": {"titre": "ETF obligations d'État américaines à 7-10 ans — IEF", "phrase": "IEF est un ETF (fonds coté en bourse) qui détient des obligations de l'État américain à moyen terme (7 à 10 ans) : son prix baisse quand les taux montent.", "mesure": "La valeur d'une part, en dollars. Une obligation est un prêt à l'État, qui verse un intérêt (le coupon) ; ici, il reste 7 à 10 ans avant le remboursement.", "calcul": "Le fonds (iShares) détient des bons du Trésor américain de 7 à 10 ans. Le cours est celui de clôture de Yahoo, hors dividendes : les intérêts versés n'étant pas ajoutés, la courbe sous-estime le rendement total de l'ETF.", "interpreter": "Plus la durée est courte, moins le prix réagit aux taux. En 2022, de fin décembre 2021 à fin décembre 2022, IEF a perdu environ 17 % (de 115 à 96 dollars environ), contre environ 33 % pour TLT (plus de 20 ans). Le taux à 10 ans américain est le repère le plus proche.", "bouger": "L'inflation attendue, les décisions de la Fed (Réserve fédérale, banque centrale américaine) et le besoin de refuge des investisseurs : le prix monte en cas de panique.", "liens": ["B1", "H12", "A1", "B2"], "piege": "Un fonds d'obligations n'a pas d'échéance fixe : contrairement à une obligation gardée jusqu'au bout, son prix ne revient pas forcément à son niveau de départ. Cours en dollars et hors coupons."},
"H14": {"titre": "ETF obligations d'État de la zone euro — IEGA (iShares Core Euro Government Bond)", "phrase": "IEGA est un ETF (fonds coté en bourse) qui détient des obligations d'États de la zone euro, de durées variées : son prix baisse quand les taux montent.", "mesure": "La valeur d'une part, en euros, cotée à Amsterdam. Une obligation est un prêt à un État, qui verse un intérêt (le coupon).", "calcul": "Cours de clôture Yahoo de la cotation d'Amsterdam (IEGA.AS), en euros, hors dividendes. Le fonds distribue ses revenus : le cours baisse du montant versé, et la courbe sous-estime donc le rendement. Le même fonds coté à Londres (en livres) n'est pas utilisé.", "interpreter": "Quand les taux montent, le cours baisse. Repère vérifié : de fin décembre 2021 (environ 131 euros) à fin décembre 2022 (environ 106 euros), −19 %, quand les taux de la zone euro ont fortement augmenté.", "bouger": "Les décisions de la BCE (Banque centrale européenne), l'inflation de la zone euro et les écarts de taux entre États (Italie ou France comparées à l'Allemagne).", "liens": ["B4", "B5_10A", "A2", "BC_IT_DE", "C5"], "piege": "Historique court, depuis juin 2014. À Amsterdam, l'ETF s'échange peu : son cours de clôture peut s'écarter un peu de la valeur du fonds. Cours en euros et hors coupons : ne pas le comparer aux ETF américains TLT ou IEF (H12, H13 ; monnaie et durées différentes)."},
"H15": {"titre": "ETF obligations américaines indexées sur l'inflation — TIP (TIPS)", "phrase": "TIP est un ETF (fonds coté en bourse) qui détient des TIPS (Treasury Inflation-Protected Securities), des obligations de l'État américain dont le capital suit l'inflation.", "mesure": "La valeur d'une part, en dollars. Le capital de ces obligations est réajusté selon l'inflation américaine : elles protègent en principe contre la hausse des prix, ce que ne font pas les obligations ordinaires.", "calcul": "Cours de clôture Yahoo, hors dividendes : les intérêts versés n'étant pas ajoutés, la courbe sous-estime le rendement total de l'ETF.", "interpreter": "Il réagit surtout aux taux d'intérêt réels (taux moins inflation attendue), pas à l'inflation seule. En 2022, malgré une inflation élevée, TIP a perdu environ 18 % de fin décembre 2021 (environ 129 dollars) à fin décembre 2022 (environ 106 dollars), car les taux réels ont fortement monté.", "bouger": "Les taux réels, l'inflation attendue par les marchés (le point mort d'inflation), les décisions de la Fed (Réserve fédérale, banque centrale américaine).", "liens": ["D1", "B1", "C1", "H13", "A1"], "piege": "Se protéger de l'inflation ne signifie pas ne pas perdre : le prix peut chuter si les taux montent. La protection ne vaut que pour l'inflation américaine, en dollars. Cours hors coupons."},
"H2": {"titre": "Pétrole WTI — la référence américaine du prix du pétrole", "phrase": "Le WTI (West Texas Intermediate) est le prix d'un baril de pétrole américain, l'autre grande référence mondiale avec le Brent.", "mesure": "Le prix en dollars d'un baril de pétrole brut américain livrable tout de suite (« au comptant »). Il évolue presque comme le Brent, mais l'écart entre les deux varie.", "calcul": "Prix relevé par l'EIA (Agence américaine d'information sur l'énergie) et repris via FRED (base de données de la Banque fédérale de réserve de Saint-Louis). Les derniers jours peuvent venir du contrat à terme Yahoo (CL=F, achat à prix fixé d'avance), mais seulement si l'écart avec FRED reste sous 2 % ; sinon la courbe s'arrête à la dernière valeur FRED.", "interpreter": "Pas de seuil officiel. Sur les valeurs de fin de mois depuis 1990, le WTI est resté sous 19 dollars un mois sur dix et au-dessus de 96 dollars un mois sur dix ; médiane : environ 50 dollars. Il a atteint environ 140 dollars fin juin 2008.", "bouger": "Mêmes moteurs que le Brent (croissance mondiale, OPEP+ : pays exportateurs de pétrole et partenaires, tensions géopolitiques), plus la production et les stocks américains.", "liens": ["H1", "H8_USO", "C1", "I6"], "piege": "Un prix de pétrole peut être négatif : le 20 avril 2020, le WTI a clôturé sous zéro (−36,98 dollars selon l'EIA via FRED), les stockages étant saturés. L'application accepte les valeurs négatives, mais l'historique mensuel ne garde que la valeur de fin de mois (19,23 dollars fin avril 2020), et aucun % de variation n'est calculé sur un prix nul ou négatif."},
"H3": {"titre": "Or — la valeur refuge, cours du contrat à terme de New York", "phrase": "L'or est un métal précieux que les investisseurs achètent souvent pour se protéger des crises, de l'inflation ou d'un affaiblissement du dollar.", "mesure": "Le prix en dollars d'une once troy (environ 31,1 grammes) d'or. L'or ne verse ni dividende ni intérêt : seul son prix compte.", "calcul": "Cours de clôture du contrat à terme sur l'or le plus proche, coté à New York (Yahoo GC=F) : un engagement d'acheter ou de vendre plus tard à un prix fixé aujourd'hui. Il suit de près le prix « au comptant », sans être identique.", "interpreter": "Pas de seuil. Repères vérifiés (fin de mois) : environ 884 dollars fin décembre 2008, 1 829 fin août 2011, puis 1 060 fin décembre 2015 : plus de 40 % de perte en un peu plus de quatre ans.", "bouger": "Il monte souvent quand les taux réels (taux moins inflation) baissent, quand le dollar faiblit, en période d'incertitude ou quand les banques centrales achètent. Il souffre quand les taux montent : l'or ne rapporte rien.", "liens": ["H9", "I6", "B1", "C1", "J3"], "piege": "Un refuge n'est pas une garantie : l'or peut baisser longtemps. Série depuis août 2000, contrat à terme (pas le comptant), en dollars : pour un Belge, l'euro joue aussi."},
"H4": {"titre": "Gaz naturel européen — le TTF, référence du prix du gaz en Europe", "phrase": "Le TTF (Title Transfer Facility) est le prix de référence du gaz naturel en Europe, coté sur un marché virtuel basé aux Pays-Bas.", "mesure": "Le prix du gaz livré prochainement, en euros par MWh (mégawattheure, mille kilowattheures). Il influence les factures de gaz, d'électricité et le coût de l'industrie européenne.", "calcul": "Cours de clôture du contrat à terme le plus proche (code Yahoo TTF=F), c'est-à-dire un achat à prix fixé aujourd'hui pour une livraison dans les semaines qui viennent.", "interpreter": "Pas de seuil officiel, historique court. Sur les valeurs de fin de mois depuis octobre 2017, la moitié des mois sont restés sous environ 32 euros, neuf sur dix sous environ 98. Extrêmes : environ 4 euros fin mai 2020 (confinements), environ 240 fin août 2022 (crise énergétique, guerre en Ukraine).", "bouger": "Le froid, le niveau des stocks européens, les livraisons par gazoduc (Norvège, Russie) et par bateaux de gaz naturel liquéfié (GNL), le prix du pétrole. Il pèse sur l'inflation de l'énergie.", "liens": ["H5", "H1", "C5", "C7"], "piege": "Historique depuis le 23 octobre 2017 seulement : trop court pour dire ce qui est « normal ». Prix de contrat à terme, pas celui payé par un ménage. En euros par MWh : ne pas le comparer au Henry Hub (dollars par mmbtu, million de British thermal units) sans conversion."},
"H5": {"titre": "Gaz naturel américain — le Henry Hub", "phrase": "Le Henry Hub est le prix de référence du gaz naturel aux États-Unis.", "mesure": "Le prix du gaz livré prochainement à Henry Hub, nœud de gazoducs de Louisiane, en dollars par mmbtu (million de British thermal units, unité d'énergie ; 1 MWh vaut environ 3,4 mmbtu). Le gaz voyage mal : ce prix reste très américain.", "calcul": "Cours de clôture du contrat à terme le plus proche (code Yahoo NG=F), coté à New York : un achat à prix fixé aujourd'hui pour livraison dans les semaines qui viennent.", "interpreter": "Pas de seuil officiel. Sur les valeurs de fin de mois depuis août 2000, la moitié des mois sont restés sous environ 3,7 dollars, un mois sur dix sous 2,3 et un sur dix au-dessus de 7,5. Extrêmes : environ 13,9 fin septembre 2005 et 1,6 fin mars 2020.", "bouger": "La météo (froid : chauffage ; canicule : climatisation), la production américaine, les stocks et les exportations de gaz naturel liquéfié (GNL).", "liens": ["H4", "H1", "H2", "C1"], "piege": "Très saisonnier et volatil. Prix de contrat à terme, pas celui payé par un ménage. En dollars par mmbtu : ne pas le comparer au TTF européen (prix de référence du gaz en Europe) (euros par MWh) sans convertir."},
"H6": {"titre": "Cuivre — le « thermomètre » de l'activité industrielle", "phrase": "Le cuivre entre dans presque tout (bâtiment, câbles, voitures, appareils) : son prix est suivi comme un indice de la santé de l'industrie mondiale.", "mesure": "Le prix en dollars d'une livre (environ 454 grammes) de cuivre. Quand l'activité est forte, les industriels en achètent beaucoup et le prix monte ; quand elle faiblit, il recule.", "calcul": "Cours de clôture du contrat à terme sur le cuivre le plus proche, coté à New York (code Yahoo HG=F) : un achat à prix fixé aujourd'hui pour une livraison future.", "interpreter": "Pas de seuil officiel. Une hausse durable suggère une demande industrielle solide ; une chute brutale traduit souvent une inquiétude sur la croissance. Repère vérifié : de fin avril 2008 (environ 3,93 dollars) à fin décembre 2008 (environ 1,40 dollar), il a perdu environ 65 % pendant la crise financière.", "bouger": "La croissance de la Chine et du reste du monde, la construction, la transition énergétique (voitures électriques, réseaux), les stocks des entreprises et le dollar.", "liens": ["E1_CN", "E1_US", "D13_CN", "H1", "I6"], "piege": "Un thermomètre imparfait : grèves, problèmes de mines, droits de douane ou spéculation peuvent déplacer le prix sans lien avec l'activité. La série commence en août 2000 et reflète un contrat à terme new-yorkais, en dollars par livre ; d'autres sources cotent en dollars par tonne."},
"H8": {"titre": "ETF pétrole — USO (WTI) et BNO (Brent)", "phrase": "USO et BNO sont des ETF (fonds cotés en bourse) qui cherchent à suivre le prix du pétrole : USO celui du WTI (West Texas Intermediate, la référence américaine), BNO celui du Brent.", "mesure": "La valeur d'une part, en dollars. Ces fonds permettent d'investir dans le pétrole depuis un compte-titres, sans acheter de contrats.", "calcul": "Ils ne stockent pas de pétrole : ils détiennent des contrats à terme proches de l'échéance, vendus juste avant pour en acheter de nouveaux (le « renouvellement »). Cours de clôture Yahoo, hors dividendes.", "interpreter": "Ne pas lire ce cours comme un prix du pétrole. Quand les contrats lointains sont plus chers que les proches, chaque renouvellement coûte. De fin 2006 à fin 2019, le WTI est resté autour de 61 dollars, mais USO est passé d'environ 413 à 102 dollars (−75 %). Pour BNO, de fin 2010 à fin 2019 : −33 %, contre −27 % pour le Brent.", "bouger": "Le prix du pétrole, mais aussi la forme de la courbe des prix à terme et le dollar.", "liens": ["H2", "H1", "H7", "I6"], "piege": "Les écarts avec le pétrole s'accumulent sur des années. L'historique d'USO a été recalculé pour tenir compte d'un regroupement d'actions en 2020 : les anciens cours semblent très élevés (plus de 900 dollars fin juin 2008) ; comparez des variations, pas des niveaux. Les deux séries sont tracées séparément ; BNO commence en juin 2010."},
"H9": {"titre": "ETF or — GLD (SPDR Gold Shares)", "phrase": "GLD est un ETF (Exchange-Traded Fund, fonds coté en bourse) dont chaque part correspond à une petite quantité d'or.", "mesure": "Le prix d'une part de GLD, en dollars. Le fonds détient de l'or physique ; sa valeur suit donc celle de l'or, diminuée de frais.", "calcul": "Cours de clôture Yahoo, hors dividendes. L'or ne rapportant ni intérêt ni dividende, ce choix ne change presque rien ici.", "interpreter": "À l'origine, une part valait environ un dixième d'once. Rapport vérifié entre le cours de GLD et celui de l'or (contrat à terme) : environ 0,100 fin 2004, environ 0,098 fin 2008, environ 0,091 fin 2025. La baisse lente vient des frais de gestion, prélevés sur l'or du fonds. Sur de longues périodes, GLD fait un peu moins bien que l'or.", "bouger": "Les mêmes facteurs que l'or : taux d'intérêt réels, dollar, incertitude, achats des banques centrales. L'afflux ou la sortie d'investisseurs joue aussi.", "liens": ["H3", "I6", "B1", "C1"], "piege": "Un ETF n'est pas l'or lui-même : frais de gestion, cotation en dollars, cours hors dividendes. L'historique commence en novembre 2004, quatre ans après celui de l'or du tableau de bord (août 2000)."},
"I1": {"titre": "EUR/USD — le cours de l'euro en dollars", "phrase": "L'EUR/USD indique combien de dollars on obtient pour 1 euro.", "mesure": "Si l'EUR/USD vaut 1,10, alors 1 € = 1,10 $. Quand il monte, l'euro s'apprécie face au dollar (il faut plus de dollars pour acheter 1 euro) ; quand il baisse, l'euro s'affaiblit. C'est la paire de devises la plus échangée au monde.", "calcul": "Taux de référence publié chaque jour ouvré par la BCE (Banque centrale européenne), fixé vers 14 h 15, heure de Francfort. La série démarre le 4 janvier 1999, premier jour de cotation de l'euro.", "interpreter": "Pas de seuil : on se repère dans l'historique mensuel. Depuis 1999, médiane d'environ 1,17 $ ; 10 % des mois sont sous 0,99 et 10 % au-dessus de 1,38. L'euro est passé sous la parité (1 € < 1 $) de 2000 à 2002, puis en septembre et octobre 2022. Extrêmes : environ 0,84 $ en octobre 2000 et 1,58 $ en mars 2008.", "bouger": "L'écart de taux entre la Fed (Réserve fédérale, banque centrale américaine) et la BCE, les écarts de croissance et d'inflation, l'appétit pour le risque (en crise, le dollar est souvent recherché). Pour un Belge, un euro fort allège les importations payées en dollars (le pétrole, par exemple : voir H1) mais rogne la valeur en euros des placements en dollars.", "liens": ["I6", "A1", "A2", "G2", "H1"], "piege": "Ne pas inverser le sens : EUR/USD en hausse = euro plus fort. L'historique affiché est mensuel ; les cours quotidiens sont des cours de référence, pas un prix en direct ni celui d'un bureau de change."},
"I2": {"titre": "USD/JPY — le cours du dollar en yens", "phrase": "L'USD/JPY indique combien de yens on obtient pour 1 dollar.", "mesure": "Si l'USD/JPY vaut 150, alors 1 $ = 150 ¥. Quand il monte, le dollar s'apprécie et le yen s'affaiblit ; quand il baisse, le yen se renforce.", "calcul": "Calculé à partir des taux de la BCE (Banque centrale européenne) : yens pour 1 euro ÷ dollars pour 1 euro, depuis janvier 1999. Avant, les données viennent de la Réserve fédérale américaine (base FRED). Le raccord se fait à date fixe, avec un petit écart d'environ 1 % le jour de la jonction.", "interpreter": "Pas de seuil : on compare à l'historique mensuel depuis 1990. Médiane d'environ 112 ¥ ; 10 % des mois sont sous 92 et 10 % au-dessus de 144. Extrêmes : environ 76 ¥ en janvier 2012 ; plus de 160 ¥ en juin 2024 et en juin 2026.", "bouger": "L'écart de taux entre les États-Unis et le Japon (A1, A5) : des taux américains bien plus élevés attirent vers le dollar. L'appétit pour le risque joue aussi, le yen étant traditionnellement recherché en période de tension.", "liens": ["IC_EURJPY", "I1", "A5", "B10", "F3"], "piege": "Le sens surprend : USD/JPY en hausse = yen plus faible. Pour un investisseur en euros, c'est l'EUR/JPY (voir IC) qui compte. Avant 1999, cours de midi à New York ; ensuite, cours de 14 h 15 à Francfort : ne pas lire une différence de quelques dixièmes de pour cent comme un vrai mouvement."},
"I3": {"titre": "USD/CNY — le cours du dollar en yuans", "phrase": "L'USD/CNY indique combien de yuans chinois on obtient pour 1 dollar.", "mesure": "Si l'USD/CNY vaut 7, alors 1 $ = 7 yuans. Quand il monte, le dollar s'apprécie et le yuan s'affaiblit ; quand il baisse, le yuan se renforce.", "calcul": "Calculé à partir des taux de la BCE (Banque centrale européenne) : yuans pour 1 euro ÷ dollars pour 1 euro, depuis le 13 janvier 2000, début du yuan dans les données de la BCE. Avant, les données viennent de la Réserve fédérale américaine (base FRED).", "interpreter": "Pas de seuil : on compare à l'historique. Dans les données, le dollar passe de 4,7 yuans en 1990 à 8,7 en 1994, reste quasi figé à environ 8,28 de 1999 à 2004, puis recule progressivement. Médiane d'environ 6,9 yuans pour 1 $.", "bouger": "Surtout la politique de la banque centrale chinoise, qui encadre le cours (A6), l'écart de taux avec les États-Unis (A1), le commerce extérieur et les flux de capitaux.", "liens": ["IC_EURCNY", "I1", "A6", "B11", "E1_CN"], "piege": "Le yuan ne flotte pas librement : son cours reflète des décisions des autorités autant que le marché. Le sens surprend : USD/CNY en hausse = yuan plus faible. Avant 2000, cours de midi à New York ; ensuite, cours de 14 h 15 à Francfort."},
"I4": {"titre": "GBP/USD — le cours de la livre sterling en dollars", "phrase": "Le GBP/USD indique combien de dollars on obtient pour 1 livre sterling.", "mesure": "Si le GBP/USD vaut 1,30, alors 1 £ = 1,30 $. Quand il monte, la livre (GBP, monnaie du Royaume-Uni) s'apprécie face au dollar ; quand il baisse, elle s'affaiblit.", "calcul": "Calculé à partir des taux de la BCE (Banque centrale européenne) : dollars pour 1 euro ÷ livres pour 1 euro, depuis janvier 1999. Avant, les données viennent de la Réserve fédérale américaine (base FRED).", "interpreter": "Pas de seuil : on compare à l'historique mensuel depuis 1990. Médiane d'environ 1,56 $ ; 10 % des mois sont sous 1,27 et 10 % au-dessus de 1,84. Extrêmes : environ 2,07 $ en octobre 2007 et 1,10 $ en septembre 2022. Décrochage visible : de 1,46 $ en mai 2016 à 1,34 $ en juin 2016, mois du référendum sur le Brexit.", "bouger": "L'écart de taux entre la Banque d'Angleterre et la Fed (Réserve fédérale, banque centrale américaine ; A4, A1), l'inflation et la croissance britanniques, l'actualité politique et l'appétit pour le risque.", "liens": ["IC_EURGBP", "I1", "A4", "B9", "F4"], "piege": "Ne pas confondre avec EUR/GBP (voir IC), dont le sens est inversé : quand le GBP/USD monte, la livre se renforce, alors qu'une hausse de l'EUR/GBP signale une livre plus faible face à l'euro. Avant 1999, cours de midi à New York ; ensuite, cours de 14 h 15 à Francfort."},
"I5": {"titre": "USD/CHF — le cours du dollar en francs suisses", "phrase": "L'USD/CHF indique combien de francs suisses on obtient pour 1 dollar.", "mesure": "Si l'USD/CHF vaut 0,90, alors 1 $ = 0,90 franc suisse (CHF). Quand il monte, le dollar s'apprécie et le franc s'affaiblit ; quand il baisse, le franc se renforce.", "calcul": "Calculé à partir des taux de la BCE (Banque centrale européenne) : francs pour 1 euro ÷ dollars pour 1 euro, depuis janvier 1999. Avant, les données viennent de la Réserve fédérale américaine (base FRED).", "interpreter": "Pas de seuil : on compare à l'historique mensuel depuis 1990. Médiane d'environ 1,12 CHF ; 10 % des mois sont sous 0,90 et 10 % au-dessus de 1,51. Extrêmes : environ 1,81 CHF en octobre 2000 et 0,77 en janvier 2026. Depuis septembre 2010, le dollar a presque toujours valu moins d'un franc (182 mois sur 194).", "bouger": "L'écart de taux entre les États-Unis et la Suisse (A1, A7), les décisions de la BNS (Banque nationale suisse) et la demande de valeurs refuges : le franc est souvent recherché en période de tension.", "liens": ["IC_EURCHF", "I1", "A7", "B12", "I6"], "piege": "Le sens surprend : USD/CHF en hausse = franc plus faible. Pour un investisseur en euros, c'est l'EUR/CHF (voir IC) qui compte. Attention aux mouvements brusques : en janvier 2015, l'EUR/CHF est passé de 1,20 à environ 1,05 en un mois. Avant 1999, cours de midi à New York ; ensuite, cours de 14 h 15 à Francfort."},
"I6": {"titre": "Indice du dollar (DXY) — le dollar face à six devises", "phrase": "Le DXY (U.S. Dollar Index, « indice du dollar américain ») indique si le dollar américain s'apprécie ou s'affaiblit en moyenne face à un panier de six autres monnaies.", "mesure": "Il compare le dollar à l'euro, au yen, à la livre sterling, au dollar canadien, à la couronne suédoise et au franc suisse. Quand l'indice monte, le dollar s'apprécie en moyenne ; quand il baisse, il s'affaiblit.", "calcul": "ICE (Intercontinental Exchange, une bourse américaine) calcule l'indice en pondérant les cours de ces six devises. L'application reprend la clôture quotidienne fournie par Yahoo Finance.", "interpreter": "Pas de seuil officiel : on se repère dans l'historique mensuel depuis 1990. Médiane d'environ 93 points ; 10 % des mois sont sous 80 et 10 % au-dessus de 106. Extrêmes : environ 120 en janvier 2002 et 72 en mars 2008.", "bouger": "Les écarts de taux entre les États-Unis et les autres zones (A1), la solidité de l'économie américaine et la demande de dollars en période de crise. Un dollar fort pèse souvent sur les matières premières cotées en dollars (H1, H3).", "liens": ["I1", "I2", "I4", "I5", "H3"], "piege": "Le panier se limite à six monnaies : ni yuan, ni peso mexicain. L'euro y pèse très lourd : un DXY en baisse reflète souvent un euro plus fort (I1). La source (Yahoo Finance) n'est pas officielle ; en cas de panne, elle serait remplacée par l'indice large du dollar de la Fed (Réserve fédérale, banque centrale américaine), un autre indice, jamais raccordé à celui-ci."},
"IC": {"titre": "Euro contre livre, franc suisse, yen et yuan", "phrase": "Ces séries indiquent combien de livres, de francs suisses, de yens ou de yuans on obtient pour 1 euro.", "mesure": "EUR/GBP (livre sterling), EUR/CHF (franc suisse), EUR/JPY (yen), EUR/CNY (yuan chinois). Si l'EUR/CHF vaut 0,95, alors 1 € = 0,95 franc suisse. Quand le chiffre monte, l'euro s'apprécie face à cette monnaie ; quand il baisse, l'euro s'affaiblit.", "calcul": "Taux de référence quotidiens de la BCE (Banque centrale européenne), fixés vers 14 h 15, heure de Francfort, repris sans calcul. L'historique commence en janvier 1999 (janvier 2000 pour le yuan).", "interpreter": "Pas de seuil : on compare à l'historique mensuel. EUR/GBP : de 0,58 (avril 2000) à 0,95 (décembre 2008). EUR/CHF : de 1,68 (octobre 2007) à moins de 1 depuis mi-2022 ; chute de 1,20 à 1,05 entre décembre 2014 et janvier 2015. EUR/JPY : de 92 (octobre 2000) à plus de 180 en 2026. EUR/CNY : de 6,67 (mars 2015) à 11,27 (décembre 2004).", "bouger": "Les écarts de taux avec la BCE (A2, A4, A5, A6, A7), la croissance et l'inflation relatives, et la recherche de valeurs refuges en période de tension. Ces cours servent à convertir en euros des placements en livres, en francs suisses, en yens ou en yuans.", "liens": ["I1", "I2", "I4", "I5", "I3"], "piege": "Le sens dépend de la paire : dans EUR/GBP, la hausse signifie un euro plus fort, alors que dans GBP/USD (I4) elle signifie une livre plus forte. Le yuan est un cas à part : les autorités chinoises encadrent son cours, qui bouge peu au jour le jour."},
"J1": {"titre": "VIX — l'« indice de la peur » du marché américain", "phrase": "Le VIX (Volatility Index, « indice de volatilité ») mesure les mouvements attendus de la bourse américaine d'ici 30 jours.", "mesure": "L'ampleur attendue des variations du S&P 500 (les 500 plus grandes sociétés américaines cotées), à la hausse comme à la baisse. Il ne dit pas si la bourse va monter ou baisser, mais si elle risque de beaucoup bouger.", "calcul": "Le Cboe (Chicago Board Options Exchange) le déduit du prix des options sur le S&P 500, qui servent d'assurance contre une baisse : plus elle coûte cher, plus le VIX monte. En % sur un an, 20 équivaut à environ 6 % de variation attendue sur un mois.", "interpreter": "Repères non officiels : sous 15, calme ; 15 à 20, normal ; 20 à 30, nervosité ; au-dessus de 30, peur ; au-dessus de 40, panique. Depuis 1990, la valeur de fin de mois est restée sous 20 dans 63 % des mois et au-dessus de 30 dans 7,5 %. Pic quotidien : 82,69 (16 mars 2020).", "bouger": "Il monte quand la bourse chute et s'envole lors des chocs (faillites bancaires, pandémie, guerre). Un VIX très élevé coïncide souvent avec un point bas de la bourse, sans règle.", "liens": ["G2", "J2", "J5", "t:percentile"], "piege": "Le VIX ne prévoit pas la direction du marché et retombe vite après un choc. Historique issu de FRED (base de la Banque fédérale de réserve de Saint-Louis, rattachée à la Fed (Réserve fédérale, la banque centrale américaine)) ; derniers jours issus de Yahoo Finance, provisoires."},
"J2": {"titre": "VSTOXX — l'« indice de la peur » du marché européen", "phrase": "Le VSTOXX mesure les mouvements que les investisseurs attendent sur les grandes actions de la zone euro d'ici 30 jours.", "mesure": "La volatilité attendue de l'Euro Stoxx 50, l'indice des 50 plus grandes sociétés de la zone euro. Comme le VIX (son équivalent américain), il ne dit pas si la bourse va monter ou baisser, mais si elle risque de beaucoup bouger.", "calcul": "STOXX, fournisseur d'indices du groupe Deutsche Börse, le déduit des prix des options sur l'Euro Stoxx 50, des contrats qui servent d'assurance contre une baisse : plus elle coûte cher, plus l'indice monte. Il s'exprime en % sur un an : 24 correspond à environ 7 % de variation attendue sur un mois.", "interpreter": "Pas de seuil officiel : situez-le dans l'historique. Depuis 1999, la valeur de fin de mois médiane est de 21 ; neuf mois sur dix sont sous 33, et 6 % seulement dépassent 40. Sommets mensuels : septembre 2002 et octobre 2008 (plus de 60). Il est en général plus élevé que le VIX.", "bouger": "Il grimpe lors des chutes de la bourse européenne et des chocs : crise bancaire, crise des dettes publiques, pandémie, guerre. Il suit souvent le VIX : les peurs se propagent d'un continent à l'autre.", "liens": ["J1", "G5", "J5", "t:correlation"], "piege": "Ne comparez pas VSTOXX et VIX au point près : ils portent sur des indices différents, et les clôtures européenne et américaine n'ont pas lieu à la même heure. Historique depuis 1999, repris du site de STOXX."},
"J3": {"titre": "GPR — l'indice de risque géopolitique de Caldara et Iacoviello", "phrase": "Le GPR (Geopolitical Risk index) mesure l'importance donnée dans la presse aux guerres, aux attentats et aux tensions entre États.", "mesure": "L'attention des médias aux événements géopolitiques inquiétants : menaces de guerre, tensions militaires, menaces nucléaires, terrorisme, début d'un conflit. Il ne mesure pas directement le risque réel, mais la place de ces sujets dans l'actualité.", "calcul": "Deux économistes, Dario Caldara et Matteo Iacoviello, comptent chaque mois la part des articles de grands quotidiens anglophones qui évoquent ces thèmes. L'échelle est fixée à 100 pour la moyenne de 1985 à 2019. Une version quotidienne existe : elle est plus nerveuse.", "interpreter": "Pas de seuil officiel. Depuis 1990, la valeur mensuelle médiane est d'environ 92 ; trois mois sur quatre sont sous 117, neuf sur dix sous 151, et 4 % seulement dépassent 200. Records : septembre 2001 (près de 500) et octobre 2001 (plus de 510) ; viennent ensuite 340 à 380 en 1991 et en 2003.", "bouger": "Il monte lors de guerres, d'attentats ou de crises diplomatiques majeures, puis redescend souvent assez vite. Il influence surtout l'humeur des marchés : prix du pétrole et de l'or, volatilité des actions.", "liens": ["J1", "H1", "H3", "J4"], "piege": "Un pic de l'indice signale une forte couverture médiatique, pas forcément un danger accru pour l'économie. La version quotidienne est mise à jour le lundi, avec jusqu'à une semaine de retard. La version mensuelle l'est début de mois. Les valeurs récentes peuvent être légèrement révisées."},
"J4": {"titre": "Indice de stress financier de la Fed de Saint-Louis (STLFSI)", "phrase": "L'indice de stress financier de la Fed (Réserve fédérale, la banque centrale des États-Unis) de Saint-Louis, dit STLFSI (St. Louis Fed Financial Stress Index), résume en un seul chiffre les tensions sur les marchés financiers américains.", "mesure": "Le niveau de tension de la finance américaine : 0 correspond à la situation normale (la moyenne depuis fin 1993). Au-dessus de 0, le stress est plus fort que d'habitude ; en dessous, il est plus faible.", "calcul": "La Banque fédérale de réserve de Saint-Louis combine chaque semaine 18 séries de marché : sept taux d'intérêt, six écarts de taux et cinq autres indicateurs, dont des mesures de volatilité. Ces séries tendent à bouger ensemble quand le stress monte. L'indice est publié chaque semaine, au vendredi.", "interpreter": "Il n'existe pas de seuil officiel. Depuis fin 1993, la valeur de fin de mois est négative environ deux mois sur trois ; elle n'a dépassé 1 que dans 7 % des mois et 2 que dans 3 %. Plus fortes valeurs de fin de mois : octobre 2008 (près de 8) et mars 2020 (plus de 5).", "bouger": "Il grimpe lors des crises bancaires, des krachs boursiers et des paniques sur le crédit. Les valeurs nettement négatives décrivent un marché calme, où le crédit est facile.", "liens": ["J1", "J5", "J6", "t:percentile"], "piege": "Un indice très bas (calme) n'est pas une garantie : le calme précède parfois les tempêtes. Attention aussi : cet indice a été révisé plusieurs fois (la quatrième version, STLFSI4, est utilisée). Son historique démarre fin 1993, soit environ 33 ans."},
"J5": {"titre": "CISS — l'indicateur de stress systémique de la BCE", "phrase": "Le CISS (Composite Indicator of Systemic Stress, « indicateur composite de stress systémique ») dit, entre 0 et 1, à quel point le système financier de la zone euro est sous tension.", "mesure": "Le stress dans l'ensemble de la finance européenne : marché monétaire (prêts à très court terme entre banques), obligations, actions, change et intermédiaires financiers. Il vise le risque que le système tout entier se grippe, pas celui d'une entreprise isolée.", "calcul": "La BCE (Banque centrale européenne) part de 15 mesures de stress, réparties en cinq segments de marché. Elle les agrège en tenant compte de leur corrélation : l'indicateur monte davantage quand le stress touche plusieurs segments à la fois. Nous utilisons la nouvelle version (« NEW CISS »), quotidienne.", "interpreter": "Il n'y a pas de seuil officiel. Depuis 1990, la valeur de fin de mois médiane est d'environ 0,06 ; trois mois sur quatre sont sous 0,18, neuf sur dix sous 0,34, et 7 % seulement dépassent 0,4. Les plus hauts datent de la crise de 2008-2009 (plus de 0,9 en octobre et novembre 2008).", "bouger": "Il monte lors des crises bancaires, des crises de la dette publique, des chocs boursiers et des paniques sur les devises, et redescend quand les marchés se calment.", "liens": ["J1", "J2", "J7", "J4"], "piege": "Seule la nouvelle version est utilisée, car l'ancienne est arrêtée depuis mai 2025. Le CISS vise la zone euro : son équivalent américain n'est pas affiché ici."},
"J6": {"titre": "Écart de crédit des entreprises américaines (GZ) et prime excédentaire (EBP)", "phrase": "Ces deux mesures de la Fed (Réserve fédérale, la banque centrale des États-Unis) chiffrent le rendement supplémentaire que les entreprises américaines offrent, face à l'État, à ceux qui leur prêtent.", "mesure": "L'écart GZ (initiales de ses auteurs, Gilchrist et Zakrajšek) est la différence moyenne entre le taux des obligations d'entreprises et celui des obligations d'État de même durée. L'EBP (Excess Bond Premium, « prime obligataire excédentaire ») en isole la part que le risque de faillite n'explique pas : l'appétit pour le risque.", "calcul": "Des chercheurs de la Fed partent des prix de nombreuses obligations d'entreprises américaines non financières. Ils en tirent l'écart moyen (GZ), puis estiment la part due au risque de défaut : le reste est l'EBP. Valeurs mensuelles, en points de pourcentage.", "interpreter": "Pas de seuil officiel. Depuis 1990, l'écart GZ médian est d'environ 1,7 point ; trois mois sur quatre sont sous 2,3 points, et 3 % seulement dépassent 4 points (maximum : plus de 7 fin 2008). L'EBP est proche de zéro en temps normal ; au-dessus de 1 point (7 % des mois), le crédit est très tendu.", "bouger": "L'écart s'élargit quand les investisseurs craignent des faillites ou fuient le risque (récession, crise, krach) et se resserre quand la confiance revient. Il annonce parfois un ralentissement.", "liens": ["J4", "J1", "J7", "t:spread"], "piege": "Recherches du personnel de la Fed, pas statistiques officielles. Publiées chaque mois avec du retard, elles peuvent voir tout leur historique révisé : le tableau de bord le retélécharge donc en entier à chaque mise à jour."},
"J7": {"titre": "Tensions obligataires en zone euro (composante du CISS)", "phrase": "Cet indicateur mesure ce que le marché obligataire apporte au stress de la zone euro, et sert d'approximation des tensions sur le crédit.", "mesure": "Les tensions sur le marché des obligations de la zone euro : volatilité des taux des États, écarts de swap (taux d'échange entre banques) et écarts de rendement des obligations privées. Ce n'est pas un écart de crédit pur : aucune série gratuite et publique de ce type n'a été trouvée pour la zone euro.", "calcul": "La BCE (Banque centrale européenne) calcule le CISS (indicateur composite de stress systémique, voir J5) à partir de cinq segments de marché. Nous affichons la contribution du segment « obligations » au CISS, publiée chaque jour.", "interpreter": "Pas de seuil officiel. Depuis 1999, la valeur de fin de mois médiane est d'environ 0,09 ; trois mois sur quatre sont sous 0,125, neuf sur dix sous 0,17, et 4 % seulement dépassent 0,2, surtout lors de la crise de 2008-2009.", "bouger": "Elle monte quand les taux des obligations d'État deviennent plus volatils ou que les écarts de swap et de crédit s'élargissent : crises bancaires, crise de la dette publique.", "liens": ["J5", "J6", "B4", "t:spread"], "piege": "Une contribution n'est pas le sous-indice brut. Les contributions des cinq segments, additionnées, dépassent le CISS, qui tient compte des corrélations entre segments (leur tendance à bouger ensemble) : une contribution peut donc être supérieure au CISS lui-même. Elle mêle obligations d'État, swaps et obligations privées. Ne la lisez pas comme l'écart de crédit américain (J6). Historique depuis 1999."},
"K": {"titre": "Valeurs suivies — des actions choisies (par défaut Aedifica)", "phrase": "Cette page suit le cours d'actions individuelles choisies pour vous ; par défaut, Aedifica, une société immobilière belge cotée à Bruxelles.", "mesure": "Le prix d'une seule action, qui reflète l'avis du marché sur une entreprise. Aedifica est une société immobilière réglementée (SIR) belge, cotée sur Euronext Bruxelles et investie surtout dans l'immobilier de santé (maisons de repos et de soins).", "calcul": "C'est la clôture quotidienne en euros, non ajustée des dividendes (« hors dividendes ») : le cours baisse mécaniquement du montant du dividende le jour où il est détaché. D'autres actions peuvent être ajoutées dans les réglages de l'outil.", "interpreter": "Pas de seuil reconnu : regardez la variation sur 12 mois et sa position dans l'historique (percentile). Repères tirés des clôtures mensuelles d'Aedifica : plus bas en octobre 2008, plus haut en août 2021, puis baisse d'environ 58 % jusqu'en octobre 2023, période de remontée des taux d'intérêt.", "bouger": "Pour une société immobilière : les taux d'intérêt (un taux élevé renchérit sa dette et rend ses loyers moins attractifs), la valeur des immeubles, les loyers, les résultats et les augmentations de capital.", "liens": ["B6", "A2", "H11", "G1", "t:dividendes"], "piege": "Hors dividendes : le rendement réel est supérieur à ce que montre la courbe, d'autant que ce type de société distribue une grande partie de son résultat. Une seule action est bien plus risquée qu'un indice."},
"t:base100": {"titre": "Base 100 — comparer des courbes de niveaux différents", "phrase": "La base 100 ramène plusieurs courbes au même point de départ, fixé à 100, pour comparer leur évolution.", "mesure": "Elle ne mesure rien de nouveau : elle change l'échelle. On compare l'or, un indice boursier ou un bilan de banque centrale, même si leurs prix n'ont aucun rapport.", "calcul": "Chaque valeur est divisée par la première valeur de la période choisie, puis multipliée par 100. Une courbe à 130 a gagné 30 % depuis le départ ; une courbe à 80 a perdu 20 %.", "interpreter": "Le but est de voir qui a le plus progressé, pas qui a le prix le plus haut. Le tableau de bord ne l'applique qu'aux prix et aux montants. Les taux et les indices (comme le VIX, indice de volatilité américain) gardent leur unité.", "bouger": "Le point de départ change tout : en changeant la période affichée, on change le 100 et donc l'allure relative des courbes. Elle ne change que l'affichage, pas le calcul des corrélations.", "liens": ["t:points", "t:correlation", "G2", "H3"], "piege": "Un choix de départ flatteur peut faire croire à un grand écart : une courbe partie d'un sommet paraît perdante. Regardez toujours plusieurs périodes. Et la base 100 n'efface pas la tendance de fond."},
"t:causalite": {"titre": "Corrélation n'est pas causalité", "phrase": "Deux courbes qui évoluent ensemble ne prouvent pas que l'une provoque l'autre.", "mesure": "Un rappel de prudence, pas une mesure. Un coefficient de corrélation élevé dit seulement que deux séries ont évolué de façon semblable dans le passé.", "calcul": "Aucun calcul : c'est un raisonnement. Trois explications sont possibles : A cause B ; B cause A ; ou une troisième cause agit sur les deux. Exemple : les glaces et les noyades augmentent l'été, parce que la chaleur agit sur les deux.", "interpreter": "Un lien statistique devient crédible quand il y a une explication économique plausible, quand il résiste à plusieurs périodes et quand la cause supposée précède l'effet dans le temps. Même alors, il reste une hypothèse.", "bouger": "Les liens changent avec le temps : ce qui valait dans les années 1990 peut ne plus valoir après une crise ou un changement de politique monétaire.", "liens": ["t:correlation", "t:decalage", "t:fiabilite", "H1"], "piege": "En testant des dizaines de combinaisons ou de décalages, on trouve toujours une corrélation flatteuse, due au hasard. Méfiez-vous des liens trouvés en cherchant, sans raison de fond."},
"t:correlation": {"titre": "Corrélation — mesurer si deux courbes bougent ensemble", "phrase": "La corrélation chiffre, entre −1 et +1, la tendance de deux séries à évoluer ensemble ou en sens inverse.", "mesure": "Le coefficient de corrélation de Pearson, noté r. +1 : les deux courbes montent et descendent toujours ensemble. −1 : l'une monte quand l'autre descend. 0 : aucun lien visible.", "calcul": "Le calcul compare, aux dates communes, les écarts de chaque série par rapport à sa moyenne. Il faut au moins 12 points communs. Trois modes : « Mouvements » (variations d'une période à l'autre, par défaut) ; « Rythmes annuels » (variations sur 12 mois pour les prix, niveaux pour les taux ; ces variations se recouvrent et gonflent r) ; « Niveaux bruts » (valeurs telles quelles, trompeuses si deux séries ont une tendance).", "interpreter": "Un |r| (valeur sans signe) inférieur à 0,2 signifie aucun lien ; de 0,2 à 0,4, un lien faible ; de 0,4 à 0,7, modéré ; à partir de 0,7, fort. Le signe + veut dire « bougent ensemble », le signe − « bougent en sens inverse ». Le seuil de fiabilité s'applique en plus.", "bouger": "Le résultat dépend de la période, de la fréquence et du mode choisis. Une crise isolée peut le fausser à elle seule.", "liens": ["t:causalite", "t:fiabilite", "t:glissante", "t:decalage"], "piege": "Deux séries qui montent toutes les deux depuis trente ans paraissent liées sans l'être. La corrélation mesure une coïncidence, pas une cause."},
"t:courbe": {"titre": "Courbe des taux — le prix de l'argent selon la durée", "phrase": "La courbe des taux relie les taux d'emprunt de l'État pour des durées de plus en plus longues (3 mois, 2 ans, 10 ans...).", "mesure": "L'attitude du marché face au temps. En temps normal, prêter plus longtemps rapporte plus : la courbe monte. Quand elle est plate ou inversée, les taux courts sont égaux ou supérieurs aux taux longs.", "calcul": "On met en regard le taux d'une obligation à chaque échéance. Le tableau de bord résume la pente par deux écarts : 10 ans moins 2 ans, et 10 ans moins 3 mois (aux États-Unis). Un écart négatif signifie une courbe inversée.", "interpreter": "Une courbe fortement pentue indique des attentes de croissance et d'inflation plus élevées. Une inversion signale que le marché attend des baisses de taux, souvent à cause d'un ralentissement. Elle a souvent précédé les récessions américaines, avec un délai variable.", "bouger": "Les taux courts suivent le taux directeur de la banque centrale ; les taux longs suivent les anticipations de croissance et d'inflation, et l'offre de dette publique.", "liens": ["BC_10A2A", "BC_10A3M", "B1", "B2", "t:spread"], "piege": "Une inversion n'est pas une alarme automatique : elle peut durer des mois ou des années avant tout ralentissement, et elle n'a pas toujours été suivie d'une récession."},
"t:decalage": {"titre": "Décalage dans le temps — un indicateur qui en précède un autre", "phrase": "Le décalage décale une courbe dans le temps pour voir si elle annonce l'autre.", "mesure": "Le délai avec lequel un indicateur semble précéder une référence. Le pétrole, par exemple, peut agir sur l'inflation avec plusieurs mois de retard.", "calcul": "Un décalage de +k signifie que l'indicateur précède la référence de k périodes : la valeur de l'indicateur à la date t est comparée à la référence à la date t + k. Le curseur va de −24 à +24 mois, dans la limite d'un tiers de la période affichée. Le bouton « Trouver le meilleur décalage » teste tous les décalages.", "interpreter": "Un décalage n'est annoncé que si le résultat dépasse le seuil de fiabilité et gagne au moins 0,10 sur le r sans décalage. Sinon : « Aucun décalage ne ressort nettement ». Le petit graphique montre si le pic est net ou plat. Le bouton n'est pas disponible en « Niveaux bruts ».", "bouger": "Le délai varie selon les périodes et les politiques monétaires. Une relation vraie à une époque peut disparaître ensuite.", "liens": ["t:correlation", "t:causalite", "t:fiabilite", "H1"], "piege": "À force d'essayer des décalages, on en trouve toujours un flatteur. La formule « semble précéder » reste prudente : un indicateur qui précède statistiquement n'en est pas forcément la cause."},
"t:dividendes": {"titre": "Prix hors dividendes — ce que montre un cours de clôture", "phrase": "Un cours hors dividendes ne compte que le prix de l'action ou du fonds, sans les dividendes versés aux actionnaires.", "mesure": "La variation du prix seul. Le rendement total d'un investisseur est plus élevé, car il touche en plus les dividendes, parfois plusieurs % par an.", "calcul": "Le tableau de bord utilise le cours de clôture brut, non ajusté (sauf le DAX allemand, qui réinvestit lui-même les dividendes, et les fonds de capitalisation, qui les réinvestissent). Quand une société verse un dividende, son cours baisse d'à peu près ce montant le jour du détachement, sans rien changer à la richesse de l'actionnaire.", "interpreter": "Pour un indice comme le S&P 500 ou le CAC 40, on lit l'évolution des prix. Certains indices, comme le DAX allemand, réinvestissent les dividendes : leur courbe est plus haute qu'un indice de prix équivalent. Les ETF immobiliers, très généreux en dividendes, montent moins vite que leur rendement réel.", "bouger": "L'écart entre prix et rendement total grandit avec le temps et avec le taux de dividende. Il pèse davantage sur l'immobilier coté et sur les actions à forts dividendes.", "liens": ["K1", "G6", "H10", "t:etf"], "piege": "Comparer un indice de prix à un indice dividendes réinvestis (ou un ETF qui distribue à un ETF qui capitalise) fausse la lecture. Pour des valeurs comme Aedifica, très axées sur le dividende, l'écart est important."},
"t:etf": {"titre": "ETF — un fonds indiciel coté en bourse", "phrase": "Un ETF (Exchange Traded Fund, « fonds négocié en bourse ») est un fonds qui reproduit un indice et s'achète comme une action.", "mesure": "Un moyen simple d'investir dans un panier de titres : actions, obligations, or, immobilier coté, pétrole. Le cours de l'ETF suit, avec de petits écarts, l'indice qu'il copie.", "calcul": "Le gestionnaire achète les titres de l'indice (ou des contrats qui le reproduisent) et émet des parts cotées. Le cours de bourse reflète la valeur des titres détenus, moins des frais annuels, souvent faibles. Le tableau de bord suit leur cours de clôture.", "interpreter": "Le cours d'un ETF sert ici de repère pour un marché entier : or (ETF or), immobilier coté, obligations, matières premières. Une même catégorie peut compter plusieurs ETF qui ne se comportent pas pareil.", "bouger": "Il suit son indice. Pour le pétrole ou les matières premières, il suit des contrats à terme, ce qui peut créer un écart durable avec le prix réel du produit.", "liens": ["H9", "H11", "H12", "t:future", "t:dividendes"], "piege": "Un ETF n'est pas l'indice : frais, écarts de suivi et devise de cotation (dollar ou euro) comptent. De plus, les cours affichés ici ne tiennent pas compte des dividendes distribués."},
"t:fiabilite": {"titre": "Seuil de fiabilité — quand une corrélation est-elle crédible ?", "phrase": "Le seuil de fiabilité écarte les corrélations qui peuvent s'expliquer par le seul hasard, quand les points disponibles sont trop peu nombreux.", "mesure": "Le plus petit |r| (valeur du coefficient de corrélation, sans signe) à partir duquel un lien est jugé fiable. Avec peu de points, un r flatteur arrive facilement par hasard.", "calcul": "Règle unique, partout dans le tableau de bord : le lien est classé « pas de lien fiable » (gris) si |r| est inférieur au plus grand des deux nombres 0,2 et 2 ÷ √n, où n est le nombre de points utilisés.", "interpreter": "Repères : n = 12 points → 0,58 ; n = 26 → 0,39 ; n = 36 → 0,33 ; n = 60 → 0,26 ; n = 100 ou plus → 0,2. Avec 12 points mensuels, il faut donc un r de plus de 0,58 pour qu'on retienne un lien.", "bouger": "Il baisse quand n augmente : sur une longue période, un petit r devient crédible. Il s'applique aussi à chaque fenêtre de la corrélation glissante.", "liens": ["t:correlation", "t:glissante", "t:causalite", "t:decalage"], "piege": "Dépasser le seuil ne prouve pas une cause : cela dit seulement que le hasard seul l'explique mal. Et un grand nombre de points rapprochés (variations sur 12 mois qui se recouvrent) donne une fausse impression de précision."},
"t:future": {"titre": "Contrat à terme (« future ») — un prix fixé aujourd'hui pour demain", "phrase": "Un contrat à terme, ou « future », est un accord d'acheter ou de vendre un produit à un prix fixé à l'avance, à une date future.", "mesure": "Le prix attendu d'une matière première pour une échéance donnée. Il sert aux producteurs et aux consommateurs à se couvrir contre les variations de prix.", "calcul": "Deux parties se mettent d'accord aujourd'hui sur un prix, avec livraison (ou règlement financier) plus tard, à une date d'échéance. Pour obtenir une courbe continue, on enchaîne les contrats : on passe au contrat suivant quand le premier approche de son échéance.", "interpreter": "Les cours du Brent (référence européenne du pétrole), du WTI (West Texas Intermediate, référence américaine), du gaz, de l'or et du cuivre affichés ici sont ceux de contrats à terme proches de leur échéance. Pour le Brent et le WTI, l'historique ancien est le prix « au comptant » publié par l'agence américaine de l'énergie (EIA, via FRED) ; seuls les jours récents sont des contrats à terme, d'où un petit décalage possible au raccord.", "bouger": "Il suit l'offre et la demande, les stocks, la météo, la géopolitique et les taux d'intérêt. Le prix du contrat peut différer du prix « au comptant » (livraison immédiate).", "liens": ["H1", "H3", "H4", "t:etf"], "piege": "Au moment de passer d'un contrat au suivant, la courbe peut présenter un petit saut qui n'est pas un vrai mouvement de prix. Le prix du contrat n'est pas non plus le prix « à la pompe » ou chez le fournisseur."},
"t:glissante": {"titre": "Corrélation glissante — un lien qui change avec le temps", "phrase": "La corrélation glissante recalcule la corrélation sur une fenêtre mobile, pour voir si le lien entre deux courbes se renforce, s'efface ou s'inverse.", "mesure": "La stabilité d'un lien. Deux séries peuvent être très liées pendant une crise et indépendantes le reste du temps : un seul r global les cacherait.", "calcul": "On calcule r sur les derniers points seulement, puis on fait avancer la fenêtre d'un point à la fois. La fenêtre compte 26 points en hebdomadaire (vue 1 an), 24 en mensuel (5 ans), 36 en mensuel (10 ans et plus). Chaque segment de courbe prend la couleur de r.", "interpreter": "Vert : les deux courbes bougent ensemble ; rouge : en sens inverse ; gris : lien non fiable. L'épaisseur du trait traduit la force. En pointillé gris, la fenêtre n'est pas encore complète. Le seuil de fiabilité s'applique à chaque fenêtre.", "bouger": "Elle change d'une fenêtre à l'autre selon les événements : crise, changement de politique monétaire. Il n'y en a pas en vue 1 mois, trop courte pour être fiable.", "liens": ["t:correlation", "t:fiabilite", "t:causalite", "J1"], "piege": "Une fenêtre courte réagit au hasard : les couleurs peuvent alors changer sans raison économique. Ne tirez pas de conclusion d'un seul virage de couleur."},
"t:glissement": {"titre": "Glissement annuel — l'évolution sur douze mois", "phrase": "Le glissement annuel compare une valeur à celle du même mois un an plus tôt, pour mesurer une évolution sans effet de saison.", "mesure": "La variation sur douze mois d'une grandeur. C'est la façon usuelle d'exprimer l'inflation : « les prix ont augmenté de 2 % en un an ».", "calcul": "Valeur du mois ÷ valeur du même mois un an plus tôt, moins 1. Exemple : un indice des prix qui passe de 100 à 102 donne un glissement annuel de +2 %. Le tableau de bord apparie les mois par date : si l'une des deux valeurs manque, le point reste vide.", "interpreter": "Il lisse les variations saisonnières (soldes, vacances, chauffage), car on compare deux mois identiques. Une inflation de 2 % signifie que le panier coûte 2 % de plus qu'il y a un an.", "bouger": "Il dépend du mois actuel et du mois d'il y a un an. Si les prix ont fortement monté il y a un an, ce mois sort du calcul et le glissement peut chuter. On parle d'« effet de base ».", "liens": ["C5", "C1", "t:points", "t:correlation"], "piege": "Un glissement annuel qui baisse ne veut pas dire que les prix baissent : ils montent simplement moins vite. De plus, il réagit tard : il décrit les douze derniers mois, pas la tendance du dernier mois."},
"t:percentile": {"titre": "Percentile — où se situe une valeur dans l'histoire", "phrase": "Le percentile indique la part des observations passées qui sont inférieures à la valeur d'aujourd'hui.", "mesure": "Une position dans l'historique. Le 85e percentile signifie que la valeur dépasse 85 % de toutes les valeurs passées (et que 15 % étaient plus hautes).", "calcul": "On classe l'historique mensuel disponible (30 ans au plus) et on retrouve le rang de la dernière valeur. Pour les prix et les cours, on classe la variation sur 12 mois et non le niveau, car un indice boursier suit une tendance de fond et serait presque toujours « au plus haut ».", "interpreter": "Moins de 10 : très bas ; 10 à 25 : bas ; 25 à 75 : habituel ; 75 à 90 : élevé ; plus de 90 : très élevé. La période réellement utilisée est toujours indiquée (« depuis 1999 »). Moins de 10 ans d'historique : mention « historique court » ; moins de 5 ans : pas de percentile.", "bouger": "Il change avec la valeur, mais aussi avec l'historique : une série qui commence en 2010 n'a pas connu la crise de 2008.", "liens": ["J1", "J2", "J4", "t:fiabilite"], "piege": "Un percentile élevé dit que la valeur est rare, pas qu'elle est mauvaise ni qu'elle va baisser. La période de comparaison compte beaucoup : comparez ce qui est comparable."},
"t:point_mort": {"titre": "Point mort d'inflation — l'inflation que les marchés anticipent", "phrase": "Le point mort d'inflation est l'inflation moyenne que le marché obligataire semble attendre sur une durée donnée.", "mesure": "Une anticipation d'inflation tirée des prix de marché, et non d'une enquête. Elle s'appelle « point mort » parce qu'elle égalise le rendement de deux obligations.", "calcul": "On retranche le rendement d'une obligation indexée sur l'inflation (qui protège le capital) du rendement d'une obligation ordinaire de même durée. La différence est l'inflation pour laquelle les deux placements rapportent autant. « 5 ans dans 5 ans » désigne l'inflation moyenne attendue de la sixième à la dixième année.", "interpreter": "Un point mort de 2 % signifie que le marché table sur environ 2 % d'inflation par an. Les banques centrales surveillent surtout l'horizon lointain, car il montre si les attentes restent ancrées sur leur objectif.", "bouger": "Il monte avec les craintes d'inflation (pétrole cher, salaires) et baisse avec les craintes de récession. Il influence les taux longs et les décisions des banques centrales.", "liens": ["D1", "D2", "D3", "H15", "t:glissement"], "piege": "Il mêle l'inflation attendue et des primes (liquidité, incertitude). Ce n'est donc pas une prévision pure. Et il porte sur les États-Unis : il ne dit rien de l'inflation en Belgique."},
"t:points": {"titre": "Points de pourcentage ou pourcentage ?", "phrase": "Quand une grandeur est déjà un pourcentage (un taux), on mesure sa variation en points de pourcentage, pas en %.", "mesure": "La distance entre deux niveaux de taux. Passer de 2 % à 3 % est une hausse de 1 point de pourcentage. C'est aussi une hausse de 50 % en relatif (1 ÷ 2), ce qui n'a pas du tout le même sens.", "calcul": "En points : nouveau taux moins ancien taux. En %, pour un prix : (nouveau ÷ ancien) − 1. Exemple : un indice qui passe de 4 000 à 4 200 gagne 5 %, mais on ne dira pas 200 points de pourcentage.", "interpreter": "Le tableau de bord mesure en points les variations des taux, de l'inflation et des indices comme le VIX (indice de volatilité américain), et en % celles des prix et des cours. Une hausse de 0,25 d'un taux directeur est donc d'un quart de point.", "bouger": "Rien ne « bouge » ici : c'est une règle de lecture. Elle influence la façon de comparer : une baisse de 1 point d'un taux de 1 % est énorme, d'un taux de 8 % elle est modeste.", "liens": ["t:glissement", "t:base100", "A2", "C5"], "piege": "Les titres de presse mélangent souvent les deux. « Le taux a augmenté de 25 % » peut vouloir dire de 4 % à 5 %, soit 1 point. Vérifiez toujours l'unité."},
"t:qeqt": {"titre": "QE et QT — quand la banque centrale gonfle ou dégonfle son bilan", "phrase": "Le QE (Quantitative Easing, « assouplissement quantitatif ») est l'achat massif de titres par une banque centrale ; le QT (Quantitative Tightening, « resserrement quantitatif ») est le mouvement inverse.", "mesure": "La politique de la banque centrale quand son taux directeur est déjà proche de zéro. Le bilan de la banque (le total de ce qu'elle détient, son actif) en est le baromètre.", "calcul": "En QE, la banque crée de la monnaie pour acheter des obligations d'État et d'autres titres : son bilan grossit. En QT, elle cesse de remplacer les titres arrivés à échéance, ou elle en revend : son bilan diminue.", "interpreter": "Le QE fait baisser les taux longs et soutient les prix des actifs ; le QT agit en sens inverse. Le tableau de bord suit les bilans de la Fed (banque centrale américaine), de la BCE (Banque centrale européenne), de la Banque du Japon et de la Banque d'Angleterre, en montants et en % du PIB (produit intérieur brut).", "bouger": "Le bilan bouge avec les décisions d'achat, mais aussi avec les échéances. Les banques centrales lancent un QE lors des crises (2008, 2020) et un QT pour retirer l'excès de monnaie.", "liens": ["F1", "F2", "A1", "t:courbe", "B1"], "piege": "Le bilan n'est pas le taux directeur : une banque peut relever ses taux et gonfler son bilan en même temps. Un bilan qui baisse peut simplement refléter des titres arrivés à échéance, pas des ventes."},
"t:spread": {"titre": "Écart de taux (spread) — la différence entre deux taux", "phrase": "Un écart de taux, ou « spread », est la différence entre deux taux d'intérêt, qui mesure en général le risque ou la durée supplémentaires que l'on accepte.", "mesure": "Le prix du risque. Exemple de calcul : si un pays emprunte à 4,5 % et un autre, plus sûr, à 2,5 %, l'écart est de 2 points de pourcentage : le marché demande 2 points de plus pour prêter au premier.", "calcul": "Taux A moins taux B, exprimé en points de pourcentage (ou en « points de base » : 100 points de base valent 1 point). On compare le plus souvent deux pays, deux durées, ou une entreprise et l'État.", "interpreter": "Un écart qui s'élargit signale plus de méfiance ; un écart qui se resserre, plus de confiance. L'écart entre pays de la zone euro mesure la prime de risque sur leur dette. L'écart entre entreprises et État mesure le risque de crédit.", "bouger": "Il s'élargit lors des crises de confiance (dette publique, banques, récession) et se resserre quand elles s'apaisent. La banque centrale peut le réduire par ses achats de titres.", "liens": ["BC_IT_DE", "BC_FR_DE", "BC_10A2A", "J6", "t:courbe"], "piege": "Un écart peut se resserrer parce que le taux du pays risqué baisse, mais aussi parce que celui du pays sûr monte. Regardez les deux taux. Et la valeur doit toujours être lue avec son unité (points ou points de base)."}
};

window.Fiches = {
  rendre: function (f, ind, id) {
    var O = window.Outils, h = O.h, K = window.Composants;
    var bloc = h("div", { class: "fiche" });
    if (f.phrase) bloc.append(h("p", { class: "fiche__phrase" }, h("strong", {}, "En une phrase : "), f.phrase));
    [["Ce que ça mesure", f.mesure], ["Comment c'est calculé", f.calcul], ["Comment l'interpréter", f.interpreter],
      ["Ce qui le fait bouger, ce qu'il influence", f.bouger], ["Piège à éviter", f.piege]].forEach(function (x) {
      if (x[1]) bloc.append(h("h3", {}, x[0]), h("p", {}, x[1]));
    });
    if (f.liens && f.liens.length) {
      var p = h("p", {}, "Voir aussi : ");
      f.liens.forEach(function (l, i) {
        var cible = window.Donnees.ind(l);
        var nom = cible ? cible.nom_court : (window.FICHES[l] ? window.FICHES[l].titre : l);
        if (i) p.append(", ");
        p.append(h("a", { href: "#", onclick: function (ev) { ev.preventDefault(); K.ouvrirFiche(l); } }, nom));
      });
      bloc.append(p);
    }
    return bloc;
  },
};
